NAME = 'CzeBKR: Czech Bible Kralicka'
BOOK = 'Luke'

CHAPTERS = {
    1: {
        1: 'Poněvadž mnozí usilovali sepsati pořádně vypravování těch věcí, kteréž u nás jisté jsou,',
        2: 'Jakž nám vydali ti, kteříž od počátku sami viděli, a služebníci toho Slova byli:',
        3: 'Vidělo se i mně, kterýž jsem toho všeho pravé povědomosti z gruntu bedlivě došel, tobě o tom pořádně vypsati, výborný Teofile,',
        4: 'Abys zvěděl jistotu těch věcí, jimž jsi vyučován.',
        5: 'Byl za dnů Heródesa krále Judského kněz nějaký, jménem Zachariáš, z třídy Abiášovy, a manželka jeho ze dcer Aronových, a jméno její Alžběta.',
        6: 'Byli pak oba spravedliví před oblíčejem Božím, chodíce ve všech přikázaních a spravedlnostech Páně bez ouhony.',
        7: 'A neměli plodu, proto že Alžběta byla neplodná, a oba se byli zstarali ve dnech svých.',
        8: 'I stalo se, když on úřad kněžský konal v pořádku třídy své před Bohem,',
        9: 'Že vedlé obyčeje úřadu kněžského los naň přišel, aby položil zápal, vejda do chrámu Páně.',
        10: 'A všecko množství lidu bylo vně, modlíce se v hodinu zápalu.',
        11: 'Tedy ukázal se jemu anděl Páně, stoje na pravé straně oltáře zápalu.',
        12: 'A uzřev jej Zachariáš, zstrašil se, a bázeň připadla na něj.',
        13: 'I řekl jemu anděl: Neboj se, Zachariáši, neboť jest uslyšána modlitba tvá, a Alžběta manželka tvá porodí tobě syna, a nazůveš jméno jeho Jan.',
        14: 'Z čehož budeš míti radost a veselé, a mnozí se z jeho narození budou radovati.',
        15: 'Bude zajisté veliký před oblíčejem Páně, a vína i nápoje opojného nebude píti, a Duchem svatým bude naplněn hned od života matky své.',
        16: 'A mnohé z synů Izraelských obrátí ku Pánu Bohu jejich.',
        17: 'Neboť on předejde před oblíčejem jeho v duchu a v moci Eliášově, aby obrátil srdce otců k synům, a nevěřící k opatrnosti spravedlivých, aby postavil Pánu lid hotový.',
        18: 'I řekl Zachariáš andělu: Po čemž to poznám? Nebo já starý jsem, a manželka má zstarala se ve dnech svých.',
        19: 'I odpověděv anděl, řekl jemu: Jáť jsem Gabriel, kterýž stojím před oblíčejem Božím, a poslán jsem, abych mluvil s tebou, a tyto věci veselé tobě zvěstoval.',
        20: 'A aj, budeš němý, a nebudeš moci mluviti až do dne, v kterémž se tyto věci stanou, proto že jsi neuvěřil řečem mým, kteréž se naplní časem svým.',
        21: 'Lid pak očekával Zachariáše, a divili se, že on tak prodléval v chrámě.',
        22: 'Vyšed pak, nemohl mluviti k nim. I srozuměli, že vidění viděl v chrámě. Nebo on návěští jim dával, a zůstal němý.',
        23: 'I stalo se, když se vyplnili dnové konání úřadu jeho, odšel do domu svého.',
        24: 'A po těch dnech počala Alžběta manželka jeho, a tajila se za pět měsíců, řkuci:',
        25: 'Že tak mi učinil Pán ve dnech, v nichž vzezřel, aby odjal mé pohanění mezi lidmi.',
        26: 'V měsíci pak šestém poslán jest anděl Gabriel od Boha do města Galilejského, kterémuž jméno Nazarét,',
        27: 'Ku panně zasnoubené muži, kterémuž jméno bylo Jozef, z domu Davidova, a jméno panny Maria.',
        28: 'I všed k ní anděl, dí: Zdráva buď milostí obdařená, Pán s tebou, požehnaná ty mezi ženami.',
        29: 'Ona pak uzřevši ho, zarmoutila se nad řečí jeho, a myslila, jaké by to bylo pozdravení.',
        30: 'I řekl jí anděl: Neboj se, Maria, nebo jsi nalezla milost u Boha.',
        31: 'A počneš v životě, a porodíš syna, a nazůveš jméno jeho Ježíš.',
        32: 'Tenť bude veliký, a Syn Nejvyššího slouti bude, a dáť jemu Pán Bůh stolici Davida otce jeho.',
        33: 'A kralovati bude v domě Jákobově na věky, a království jeho nebude konce.',
        34: 'I řekla Maria andělu: Kterak se to stane, poněvadž já muže nepoznávám?',
        35: 'A odpověděv anděl, řekl jí: Duch svatý sstoupí v tě, a moc Nejvyššího zastíní tobě; a protož i to, což se z tebe svatého narodí, slouti bude Syn Boží.',
        36: 'A aj, Alžběta, přítelkyně tvá, i ona počala syna v starosti své, a tento jest jí šestý měsíc, kteráž sloula neplodná.',
        37: 'Neboť nebude nemožné u Boha žádné slovo.',
        38: 'I řekla Maria: Aj, děvka Páně, staniž mi se podlé slova tvého. I odšel od ní anděl.',
        39: 'Tedy povstavši Maria v těch dnech, odešla na hory s chvátáním do města Judova.',
        40: 'I vešla do domu Zachariášova, a pozdravila Alžběty.',
        41: 'I stalo se, jakž uslyšela Alžběta pozdravení Marie, zplésalo nemluvňátko v životě jejím, a naplněna jest Duchem svatým Alžběta.',
        42: 'I zvolala hlasem velikým a řekla: Požehnaná ty mezi ženami, a požehnaný plod života tvého.',
        43: 'A odkud mi to, aby přišla matka Pána mého ke mně?',
        44: 'Nebo aj, jakž se stal hlas pozdravení tvého v uších mých, zplésalo radostně nemluvňátko v životě mém.',
        45: 'A blahoslavená, kteráž uvěřila, neboť dokonány budou ty věci, kteréž jsou povědíny jí ode Pána.',
        46: 'Tedy řekla Maria: Velebí duše má Hospodina,',
        47: 'A veselí se duch můj v Bohu, spasiteli svém,',
        48: 'Že vzezřel na ponížení děvky své; neb aj, od této chvíle blahoslaviti mne budou všickni národové.',
        49: 'Neboť mi učinil veliké věci ten, kterýž mocný jest, a svaté jméno jeho,',
        50: 'A jehož milosrdenství od pokolení až do pokolení bojícím se jeho.',
        51: 'Dokázal moci ramenem svým, rozptýlil pyšné myšlením srdce jejich.',
        52: 'Sházel mocné s stolic, a povýšil ponížených.',
        53: 'Lačné nakrmil dobrými věcmi, a bohaté pustil prázdné.',
        54: 'Přijal Izraele, služebníka svého, byv pamětliv na milosrdenství,',
        55: 'Jakož mluvil otcům našim, Abrahamovi a semeni jeho na věky.',
        56: 'I zůstala Maria s ní asi za tři měsíce, a navrátila se do domu svého.',
        57: 'Alžbětě pak naplnil se čas, aby porodila, i porodila syna.',
        58: 'A uslyšeli sousedé a přátelé její, že Hospodin veliké učinil s ní milosrdenství své, i radovali se spolu s ní.',
        59: 'Stalo se pak v den osmý, přišli obřezovati dítěte, a nazývali jej jménem otce jeho Zachariášem.',
        60: 'Ale odpověděvši matka jeho, řekla: Nikoli, ale slouti bude Jan.',
        61: 'I řekli jí: Však žádného není v rodu tvém, kterýž by sloul jménem tím.',
        62: 'I dávali návěští otci jeho, jak by ho chtěl nazývati.',
        63: 'A on požádav deštičky, napsal, řka: Jan jest jméno jeho. I divili se všickni.',
        64: 'A hned otevřela se ústa jeho a jazyk jeho, i mluvil, velebě Boha.',
        65: 'Tedy přišla bázeň na všecky sousedy jejich, a po všech horách Judských rozhlásána jsou všecka ta slova.',
        66: 'A všickni, kteříž o tom slyšeli, skládali to v srdci svém, řkouce: I jaké dítě toto bude? A ruka Páně byla s ním.',
        67: 'Zachariáš pak otec jeho naplněn jest Duchem svatým, a prorokoval, řka:',
        68: 'Požehnaný Pán Bůh Izraelský, že navštívil a učinil vykoupení lidu svému.',
        69: 'A vyzdvihl nám roh spasení v domě Davida, služebníka svého,',
        70: 'Jakož mluvil skrze ústa proroků svých svatých, kteříž byli od věků,',
        71: 'O vysvobození z nepřátel našich, a z ruky všech, kteříž nás nenáviděli,',
        72: 'Aby učinil milosrdenství s otci našimi, a rozpomenul se na smlouvu svou svatou,',
        73: 'Na přísahu, kterouž přisáhl Abrahamovi, otci našemu, žeť nám to dá,',
        74: 'Abychom bez strachu, z ruky nepřátel svých jsouce vysvobozeni, sloužili jemu,',
        75: 'V svatosti a v spravedlnosti před oblíčejem jeho, po všecky dny života svého.',
        76: 'Ty pak, dítě, prorokem Nejvyššího slouti budeš, nebo předejdeš před tváří Páně připravovati cesty jeho,',
        77: 'Aby dáno bylo umění spasitelné lidu jeho na odpuštění hříchů jejich,',
        78: 'Skrze střeva milosrdenství Boha našeho, v nichž navštívil nás, vyšed z výsosti,',
        79: 'Aby se ukázal sedícím v temnostech a v stínu smrti, k spravení noh našich na cestu pokoje.',
        80: 'Dítě pak rostlo, a posilovalo se v duchu, a bylo na poušti až do dne zjevení svého lidu Izraelskému.',
    },
    2: {
        1: 'I stalo se v těch dnech, vyšlo poručení od císaře Augusta, aby byl popsán všecken svět.',
        2: '(To popsání nejprvé stalo se, když vládařem Syrským byl Cyrenius.)',
        3: 'I šli všickni, aby zapsáni byli, jeden každý do svého města.',
        4: 'Vstoupil pak i Jozef od Galilee z města Nazarétu do Judstva, do města Davidova, kteréž slove Betlém, (proto že byl z domu a z čeledi Davidovy,)',
        5: 'Aby zapsán byl s Marií, zasnoubenou sobě manželkou těhotnou.',
        6: 'I stalo se, když tam byli, naplnili se dnové, aby porodila.',
        7: 'I porodila Syna svého prvorozeného, a plénkami ho obvinula, a položila jej v jeslech, proto že neměli místa v hospodě.',
        8: 'A pastýři byli v krajině té, ponocujíce, a stráž noční držíce nad svým stádem.',
        9: 'A aj, anděl Páně postavil se podlé nich, a sláva Páně osvítila je. I báli se bázní velikou.',
        10: 'Tedy řekl jim anděl: Nebojtež se; nebo aj, zvěstuji vám radost velikou, kteráž bude všemu lidu.',
        11: 'Nebo narodil se vám dnes spasitel, kterýž jest Kristus Pán, v městě Davidově.',
        12: 'A toto vám bude za znamení: Naleznete nemluvňátko plénkami obvinuté, ležící v jeslech.',
        13: 'A hned s andělem zjevilo se množství rytířstva nebeského, chválících Boha a řkoucích:',
        14: 'Sláva na výsostech Bohu, a na zemi pokoj, lidem dobrá vůle.',
        15: 'I stalo se, jakž odešli od nich andělé do nebe, že ti pastýři řekli vespolek: Poďme až do Betléma, a vizme tu věc, kteráž se stala, o níž Pán oznámil nám.',
        16: 'I přišli, chvátajíce, a nalezli Marii a Jozefa, i to nemluvňátko ležící v jeslech.',
        17: 'A viděvše, rozhlašovali, což jim povědíno bylo o tom děťátku.',
        18: 'I divili se všickni, kteříž slyšeli o tom, což jim bylo mluveno od pastýřů.',
        19: 'Ale Maria zachovávala všecky věci tyto, skládajici je v srdci svém.',
        20: 'I navrátili se pastýři, velebíce a chválíce Boha ze všeho, což slyšeli a viděli, tak jakž bylo jim povědíno.',
        21: 'A když se naplnilo dní osm, aby obřezáno bylo to děťátko, i nazváno jest jméno jeho Ježíš, kterýmž bylo nazváno od anděla, prvé než se v životě počalo.',
        22: 'A když se naplnili dnové očišťování Marie podlé zákona Mojžíšova, přinesli jej do Jeruzaléma, aby ho postavili Pánu,',
        23: '(Jakož psáno jest v zákoně Páně, že každý pacholík, otvíraje život, svatý Pánu slouti bude,)',
        24: 'A aby dali obět, jakož povědíno jest v zákoně Páně, dvě hrdličky aneb dvé holoubátek.',
        25: 'A aj, byl člověk v Jeruzalémě, jemuž jméno Simeon. A člověk ten byl spravedlivý a nábožný, očekávající potěšení Izraelského, a Duch svatý byl v něm.',
        26: 'A bylo jemu zjeveno od Ducha svatého, že neuzří smrti, až by prvé uzřel Krista Páně.',
        27: 'Ten přišel, ponuknut byv od Ducha, do chrámu. A když uvodili rodičové Ježíše děťátko, aby učinili podlé obyčeje zákona při něm,',
        28: 'Tedy on vzal jej na lokty své, i chválil Boha a řekl:',
        29: 'Nyní propouštíš služebníka svého, Pane, podlé slova svého, v pokoji.',
        30: 'Nebo viděly oči mé spasení tvé,',
        31: 'Kteréž jsi připravil před oblíčejem všech lidí,',
        32: 'Světlo k zjevení národům, a slávu lidu tvého Izraelského.',
        33: 'Otec pak a matka jeho divili se těm věcem, kteréž praveny byly o něm.',
        34: 'I požehnal jim Simeon, a řekl Marii, matce jeho: Aj, položen jest tento ku pádu a ku povstání mnohým v Izraeli, a na znamení, kterémuž bude odpíráno,',
        35: '(A tvou vlastní duši pronikne meč,) aby zjevena byla z mnohých srdcí myšlení.',
        36: 'Byla také Anna prorokyně, dcera Fanuelova z pokolení Asser. Ta se byla zstarala ve dnech mnohých, a živa byla s mužem sedm let od panenství svého.',
        37: 'A ta vdova byla, v letech okolo osmdesáti a čtyřech, kteráž nevycházela z chrámu, posty a modlitbami sloužeci Bohu dnem i nocí.',
        38: 'A ta v touž hodinu přišedši, chválila Pána, a mluvila o něm všechněm, kteříž čekali vykoupení v Jeruzalémě.',
        39: 'Vykonavše pak všecko podlé zákona Páně, vrátili se do Galilee, do města svého Nazaréta.',
        40: 'Děťátko pak rostlo, a posilovalo se v duchu, plné moudrosti, a milost Boží byla v něm.',
        41: 'I chodívali rodičové jeho každého roku do Jeruzaléma na den slavný velikonoční.',
        42: 'A když byl ve dvanácti letech, a oni vstupovali do Jeruzaléma, podlé obyčeje toho dne svátečního,',
        43: 'A když vykonali ty dni, a již se navracovali, zůstalo dítě Ježíš v Jeruzalémě, a nevěděli Jozef a matka jeho.',
        44: 'Domnívajíce se pak o něm, že by byl v zástupu, ušli den cesty. I hledali ho mezi příbuznými a mezi známými.',
        45: 'A nenalezše jeho, navrátili se do Jeruzaléma, hledajíce ho.',
        46: 'I stalo se po třech dnech, že nalezli jej v chrámě, an sedí mezi doktory, poslouchaje jich, a otazuje se jich.',
        47: 'A děsili se všickni, kteříž jej slyšeli, nad rozumností a odpovědmi jeho.',
        48: 'A uzřevše ho, ulekli se. I řekla matka jeho k němu: Synu, proč jsi nám tak učinil? Aj, otec tvůj a já s bolestí hledali jsme tebe.',
        49: 'I řekl jim: Co, že jste mne hledali? Zdaliž jste nevěděli, že v těch věcech, kteréž jsou Otce mého, musím já býti?',
        50: 'Ale oni nesrozuměli těm slovům, kteráž jim mluvil.',
        51: 'I šel s nimi, a přišel do Nazaréta, a byl poddán jim. Matka pak jeho zachovávala všecka slova ta v srdci svém.',
        52: 'A Ježíš prospíval moudrostí, a věkem, a milostí, u Boha i u lidí.',
    },
    3: {
        1: 'Léta pak patnáctého císařství Tiberia císaře, když Pontský Pilát spravoval Judstvo, a Heródes byl čtvrtákem v Galilei, Filip pak bratr jeho byl čtvrtákem Iturejské a Trachonitidské krajiny, a Lyzaniáš čtvrtákem Abilinským,',
        2: 'Za nejvyššího kněze {biskupa} Annáše a Kaifáše, stalo se slovo Páně k Janovi synu Zachariášovu na poušti.',
        3: 'I chodil po vší okolní krajině Jordánské, káže křest pokání na odpuštění hříchů,',
        4: 'Jakož psáno jest v knize proroctví Izaiáše proroka, řkoucího: Hlas volajícího na poušti: Připravujte cestu Páně, přímé čiňte stezky jeho.',
        5: 'Každé údolí bude vyplněno, a každá hora a pahrbek bude ponížen; i budou křivé věci spraveny, a ostré cesty budou hladké.',
        6: 'A uzříť všeliké tělo spasení Boží.',
        7: 'Pravil pak zástupům vycházejícím, aby se křtili od něho: Plemeno ještěrčí, kdo vám ukázal, kterak byste utekli budoucího hněvu?',
        8: 'Protož neste ovoce hodné pokání, a neříkejtež u sebe: Otce máme Abrahama. Neboť pravím vám, že jest mocen Bůh z kamení tohoto vzbuditi syny Abrahamovi.',
        9: 'A jižť jest i sekera k kořenu stromů přiložena. Protož každý strom, kterýž nenese ovoce dobrého, vyťat a na oheň uvržen bývá.',
        10: 'I tázali se ho zástupové, řkouce: Což tedy činiti budeme?',
        11: 'A odpovídaje, pravil jim: Kdo má dvě sukně, dej nemajícímu, a kdo má pokrmy, tolikéž učiň.',
        12: 'Přišli pak i celní křtíti se, i řekli jemu: Mistře, co budeme činiti?',
        13: 'A on řekl jim: Nic více nevybírejte mimo to, což jest ustaveno.',
        14: 'I tázali se ho také i žoldnéři, řkouce: A my což činiti budeme? I řekl jim: Nad žádným se nepotřásejte, aniž podvodně čiňte, a dosti mějte na svých žoldích.',
        15: 'A když pak lid očekával, a myslili všickni v srdcích svých o Janovi, nebyl-li by snad on Kristus,',
        16: 'Odpověděl Jan všechněm, řka: Jáť zajisté křtím vás vodou, ale jdeť silnější nežli já, kterémuž nejsem hoden rozvázati řeménka u obuvi jeho. Tenť vás křtíti bude Duchem svatým a ohněm.',
        17: 'Jehožto věječka v ruce jeho, a vyčistíť humno své, a shromáždí pšenici do obilnice své, ale plevy páliti bude ohněm neuhasitelným.',
        18: 'A tak mnohé i jiné věci, napomínaje, zvěstoval lidu.',
        19: 'Heródes pak čtvrták, když od něho byl trestán pro Herodiadu manželku Filipa bratra svého, i ze všech nešlechetností, kteréž činil Heródes,',
        20: 'Přidal i toto nade všecko, že vsadil Jana do žaláře.',
        21: 'I stalo se, když se křtil všecken lid, a když se pokřtil i Ježíš, a modlil se, že otevřelo se nebe.',
        22: 'A sstoupil Duch svatý v tělesné způsobě jako holubice na něj, a stal se hlas s nebe, řkoucí: Ty jsi ten Syn můj milý, v toběť mi se zalíbilo.',
        23: 'Ježíš pak počínal býti jako ve třidcíti letech, jakž domnín byl, syn Jozefův, kterýž byl syn Heli,',
        24: 'Kterýž byl Matatův, kterýž byl Léví, kterýž byl Melchův, kterýž byl Jannův, kterýž byl Jozefův,',
        25: 'Kterýž byl Matatiášův, kterýž byl Amosův, kterýž byl Naum, kterýž byl Esli, kterýž byl Nagge,',
        26: 'Kterýž byl Mahatův, kterýž byl Matatiášův, kterýž byl Semei, kterýž byl Jozefův, kterýž byl Judův,',
        27: 'Kterýž byl Johannův, kterýž byl Resův, kterýž byl Zorobábelův, kterýž byl Salatielův, kterýž byl Neriův,',
        28: 'Kterýž byl Melchiův, kterýž byl Addiův, kterýž byl Kozamův, kterýž byl Elmódamův, kterýž byl Erův,',
        29: 'Kterýž byl Józův, kterýž byl Eliezerův, kterýž byl Jórimův, kterýž byl Matatův, kterýž byl Léví,',
        30: 'Kterýž byl Simeonův, kterýž byl Judův, kterýž byl Jozefův, kterýž byl Jónamův, kterýž byl Eliachimův,',
        31: 'Kterýž byl Meleův, kterýž byl Ménamův, kterýž byl Matatanův, kterýž byl Nátanův, kterýž byl Davidův,',
        32: 'Kterýž byl Jesse, kterýž byl Obédův, kterýž byl Bózův, kterýž byl Salmonův, kterýž byl Názonův,',
        33: 'Kterýž byl Aminadabův, kterýž byl Aramův, kterýž byl Ezromův, kterýž byl Fáresův, kterýž byl Judův, kterýž byl Jákobův,',
        34: 'Kterýž byl Izákův, kterýž byl Abrahamův, kterýž byl Táre, kterýž byl Náchorův,',
        35: 'Kterýž byl Sáruchův, kterýž byl Ragaův, kterýž byl Fálekův, kterýž byl Heberův, kterýž byl Sále,',
        36: 'Kterýž byl Kainanův, kterýž byl Arfaxadův, kterýž byl Semův, kterýž byl Noé, kterýž byl Lámechův,',
        37: 'Kterýž byl Matuzalémův, kterýž byl Enochův, kterýž byl Járedův, kterýž byl Malalehelův, kterýž byl Kainanův.',
        38: 'Kterýž byl Enosův, kterýž byl Setův, kterýž byl Adamův, kterýž byl Boží.',
    },
    4: {
        1: 'Ježíš pak, pln byv Ducha svatého, vrátil se od Jordánu, a puzen jest v Duchu na poušť.',
        2: 'A za čtyřidceti dní pokoušín byl od ďábla, a nic nejedl v těch dnech. Ale když se skonali, potom zlačněl.',
        3: 'I řekl jemu ďábel: Jestliže jsi Syn Boží, rci kamenu tomuto, ať jest chléb.',
        4: 'I odpověděl jemu Ježíš, řka: Psánoť jest: Že ne samým chlebem živ bude člověk, ale každým slovem Božím.',
        5: 'I vedl jej ďábel na horu vysokou, a ukázal mu všecka království okršlku země pojednou.',
        6: 'A řekl jemu ďábel: Toběť dám tuto všecku moc i slávu; nebo mně dána jest, a komuž bych koli chtěl, dám ji.',
        7: 'Protož ty pokloníš-li se přede mnou, budeť všecko tvé.',
        8: 'I odpověděv Ježíš, řekl jemu: Jdi pryč ode mne, satanáši; nebo psáno jest: Pánu Bohu svému budeš se klaněti, a jemu samému sloužiti.',
        9: 'Tedy vedl jej do Jeruzaléma, a postavil ho na vrchu chrámu, a řekl mu: Jsi-li Syn Boží, pusť se odtud dolů.',
        10: 'Nebo psáno jest: Že andělům svým přikáže o tobě, aby tě ostříhali,',
        11: 'A že tě na ruce uchopí, abys neurazil o kámen nohy své.',
        12: 'A odpovídaje, dí mu Ježíš: Povědínoť jest: Nebudeš pokoušeti Pána Boha svého.',
        13: 'A dokonav všecka pokušení ďábel, odšel od něho až do času.',
        14: 'I navrátil se Ježíš v moci Ducha do Galilee, a vyšla pověst o něm po vší té okolní krajině.',
        15: 'A on učil v školách jejich, a slaven byl ode všech.',
        16: 'I přišel do Nazaréta, kdež byl vychován, a všel podlé obyčeje svého v den sobotní do školy. I vstal, aby četl.',
        17: 'I dána jemu kniha Izaiáše proroka. A otevřev knihu, nalezl místo, kdež bylo napsáno:',
        18: 'Duch Páně nade mnou, proto že pomazal mne, kázati evangelium chudým poslal mne, a uzdravovati skroušené srdcem, zvěstovati jatým propuštění a slepým vidění, a propustiti ssoužené v svobodu,',
        19: 'A zvěstovati léto Páně vzácné.',
        20: 'A zavřev knihu, a vrátiv služebníku, posadil se. A všech v škole oči byly obráceny naň.',
        21: 'I počal mluviti k nim: Že dnes naplnilo se písmo toto v uších vašich.',
        22: 'A všickni jemu posvědčovali, a divili se libým slovům, pocházejícím z úst jeho, a pravili: Zdaliž tento není syn Jozefův?',
        23: 'I dí k nim: Zajisté díte mi toto podobenství: Lékaři, uzdrav se sám. Které věci slyšeli jsme, žes činil v Kafarnaum, učiň i zde v své vlasti.',
        24: 'I řekl jim: Amen pravím vám, žeť žádný prorok není vzácen v vlasti své.',
        25: 'Ale v pravdě pravím vám, že mnoho vdov bylo za dnů Eliáše v lidu Izraelském, když zavříno bylo nebe za tři léta a za šest měsíců, a když byl hlad veliký po vší zemi,',
        26: 'Však Eliáš k žádné z nich není poslán, než toliko do Sarepty Sidonské k ženě vdově.',
        27: 'A mnoho malomocných bylo v lidu Izraelském za Elizea proroka, a však žádný z nich není očištěn, než Náman Syrský.',
        28: 'I naplněni byli všickni v škole hněvem, slyšíce to.',
        29: 'A povstavše, vyvedli jej ven z města, a vedli ho až na vrch hory, na níž město jejich bylo vzděláno, aby jej dolů sstrčili.',
        30: 'Ale on bera se prostředkem jich, ušel.',
        31: 'I sstoupil do Kafarnaum, města Galilejského, a učil je ve dny sobotní.',
        32: 'I divili se velmi učení jeho, nebo mocná byla řeč jeho.',
        33: 'Byl pak v škole člověk, mající ducha ďábelství nečistého. I zvolal hlasem velikým,',
        34: 'Řka: Ach, což jest tobě do nás, Ježíši Nazaretský? Přišel jsi zatratiti nás? Znám tě, kdo jsi, že ten Svatý Boží.',
        35: 'I přimluvil jemu Ježíš, řka: Umlkniž a vyjdi od něho. A povrha jej ďábel mezi ně, vyšel od něho, a nic mu neuškodil.',
        36: 'I přišel strach na všecky, a rozmlouvali vespolek, řkouce: Jaké jest toto slovo, že v moci a síle přikazuje nečistým duchům, a vycházejí?',
        37: 'I rozcházela se o něm pověst po všelikém místě té okolní krajiny.',
        38: 'Vstav pak ze školy, všel do domu Šimonova. Svegruše pak Šimonova trápena byla těžkou zimnicí. I prosili ho za ni.',
        39: 'Tedy stoje nad ní, přimluvil zimnici, i přestala jí. A ona hned vstavši, posluhovala jim.',
        40: 'Při západu pak slunce všickni, kteříž měli nemocné rozličnými neduhy, vodili je k němu, a on na jednoho každého z nich ruce vzkládav, uzdravoval je.',
        41: 'Od mnohých také ďábelství vycházela, křičící a říkající: Ty jsi Kristus, Syn Boží. Ale přimlouvaje, nedopouštěl jim mluviti; nebo věděli, že jest on Kristus.',
        42: 'A jakž byl den, vyšed, bral se na pusté místo. I hledali ho zástupové, a přišli až k němu, a zdržovali ho, aby neodcházel od nich.',
        43: 'On pak řekl jim: I jinýmť městům musím zvěstovati království Boží; nebo na to poslán jsem.',
        44: 'I kázal v školách Galilejských.',
    },
    5: {
        1: 'Stalo se pak, když se zástup na něj valil, aby slyšeli slovo Boží, že on stál podlé jezera Genezaretského.',
        2: 'I uzřel dvě lodí, any stojí u jezera, rybáři pak sstoupivše z nich, vypírali sítí.',
        3: 'I vstoupiv na jednu z těch lodí, kteráž byla Šimonova, prosil ho, aby od země odvezl maličko. A posadiv se, učil z lodí zástupy.',
        4: 'A když přestal mluviti, dí k Šimonovi: Vez na hlubinu, a rozestřete síti své k lovení.',
        5: 'I odpověděv Šimon, řekl jemu: Mistře, přes celou noc pracovavše, nic jsme nepopadli, ale k slovu tvému rozestru síť.',
        6: 'A když to učinili, zahrnuli množství veliké ryb, tak že se trhala síť jejich.',
        7: 'I ponukli tovaryšů, kteříž byli na druhé lodí, aby přišli a pomohli jim. I přišli a naplnili obě lodí, tak že se pohřižovaly.',
        8: 'To uzřev Šimon Petr, padl k nohám Ježíšovým, řka: Odejdi ode mne, Pane, neboť jsem člověk hříšný.',
        9: 'Hrůza zajisté byla jej obklíčila, i všecky, kteříž s ním byli, nad tím lovením ryb, kteréž byli popadli,',
        10: 'A též Jakuba a Jana, syny Zebedeovy, kteříž byli tovaryši Šimonovi. I dí Šimonovi Ježíš: Nebojž se. Již od tohoto času lidi budeš loviti.',
        11: 'A přivezše k břehu lodí, a všecko opustivše, šli za ním.',
        12: 'I stalo se, když byl v jednom městě, a aj, muž plný malomocenství. A uzřev Ježíše, padl na tvář, a prosil ho, řka: Pane, kdybys chtěl, můžeš mne očistiti.',
        13: 'I vztáhl ruku, dotekl se ho, řka: Chci, buď čist. A hned odešlo od něho malomocenství.',
        14: 'I přikázal jemu, aby žádnému nepravil, ale jdi, ukaž se knězi, a obětuj za očištění své, jakož přikázal Mojžíš, na svědectví jim.',
        15: 'Tedy rozhlašovala se více řeč o něm, a scházeli se zástupové mnozí, aby jej slyšeli, a uzdravováni byli od něho v svých nemocech.',
        16: 'On pak odcházel na pouště, a modlil se.',
        17: 'I stalo se v jeden den, že on učil. A seděli také tu i farizeové a zákona učitelé, kteříž se byli sešli ze všech městeček Galilejských a Judských i z Jeruzaléma, a moc Páně přítomna byla k uzdravování jich.',
        18: 'A aj, muži nesli na loži člověka, kterýž byl šlakem poražený, i hledali vnésti ho a položiti před něj.',
        19: 'A nenalezše, kterou by jej stranou vnesli pro zástup, vstoupili na dům, a skrze podlahu spustili jej s ložem u prostřed před Ježíše.',
        20: 'Kterýžto viděv víru jejich, řekl mu: Člověče, odpuštěniť jsou tobě hříchové tvoji.',
        21: 'Tedy počali přemyšlovati zákonníci a farizeové, řkouce: Kdo jest tento, kterýž mluví rouhání? Kdo může odpustiti hříchy, jediné sám Bůh?',
        22: 'Poznav pak Ježíš myšlení jejich, odpovídaje, řekl jim: Co přemyšlujete v srdcích svých?',
        23: 'Co jest snáze říci: Odpouštějí se tobě hříchové tvoji, čili říci: Vstaň a choď?',
        24: 'Ale abyste věděli, že Syn člověka má moc na zemi odpouštěti hříchy, řekl šlakem poraženému: Toběť pravím: Vstaň, a vezma lože své, jdi do domu svého.',
        25: 'A hned vstav před nimi, vzal, na čemž ležel, i odšel do domu svého, velebě Boha.',
        26: 'I užasli se všickni, a velebili Boha, a naplněni jsou bázní, řkouce: Viděli jsme dnes divné věci.',
        27: 'A potom vyšel a uzřel celného, jménem Léví, sedícího na cle. I řekl jemu: Poď za mnou.',
        28: 'A opustiv všecko, vstav, šel za ním.',
        29: 'I učinil jemu hody veliké Léví v domě svém, a byl zástup veliký publikánů i jiných, kteříž s ním stolili.',
        30: 'Tedy reptali zákonníci a farizeové, řkouce učedlníkům jeho: Proč s publikány a hříšníky jíte a pijete?',
        31: 'I odpověděv Ježíš, řekl jim: Nepotřebujíť zdraví lékaře, ale nemocní.',
        32: 'Nepřišelť jsem volati spravedlivých, ale hříšných ku pokání.',
        33: 'A oni řekli jemu: Proč učedlníci Janovi postí se často a modlí se, podobně i farizejští, tvoji pak jedí a pijí?',
        34: 'On pak řekl jim: Zdali můžete synům ženicha, dokudž s nimi jest ženich, kázati se postiti?',
        35: 'Přijdouť pak dnové, když odjat bude od nich ženich, tehdážť se budou postiti v těch dnech.',
        36: 'Pravil pak jim i podobenství. Že žádný záplaty roucha nového nepřišívá k rouchu vetchému; sic jinak to nové roztrhuje, a vetchému nepřipadá záplata z nového.',
        37: 'A žádný nevlévá vína nového do nádob starých; sic jinak víno nové rozpučí nádoby, a samo vyteče, a nádoby se pokazí.',
        38: 'Ale víno nové v nádoby nové má lito býti, a obé bude zachováno.',
        39: 'A aniž kdo, když pije staré, hned chce nového, ale díť: Staré lepší jest.',
    },
    6: {
        1: 'I stalo se v druhou sobotu, že šel Ježíš skrze obilí. I trhali učedlníci jeho klasy, a rukama vymínajíce, jedli.',
        2: 'Tehdy někteří z farizeů řekli jim: Proč činíte, čehož nesluší činiti v sobotu?',
        3: 'I odpověděv Ježíš, řekl jim: Což jste ani toho nečtli, co učinil David, když lačněl, on i ti, kteříž s ním byli?',
        4: 'Kterak všel do domu Božího, a chleby posvátné vzal a jedl, a dal i těm, kteříž s ním byli, jichž nenáleží jísti než toliko samým kněžím?',
        5: 'I řekl jim: Že jest Syn člověka pánem také i dne sobotního.',
        6: 'Stalo se pak i v jinou sobotu, že všel do školy Ježíš a učil. A byl tu člověk, jehož pravá ruka byla uschlá.',
        7: 'I šetřili ho zákonníci a farizeové, bude-li v sobotu uzdravovati, aby nalezli, z čeho by jej obžalovali.',
        8: 'Ale on znal přemyšlování jejich. I dí člověku, kterýž měl ruku uschlou: Vstaň, a stůj v prostředku. A on vstav, stál.',
        9: 'Tedy řekl jim Ježíš: Otíži se vás na jednu věc: Sluší-li v sobotu dobře činiti, čili zle, duši zachovati, čili zatratiti?',
        10: 'A pohleděv na ně na všecky vůkol, dí člověku tomu: Vztáhni tu ruku svou. A on učinil tak. I přivedena jest k zdraví ruka jeho jako druhá.',
        11: 'Oni pak naplněni jsou hněvivou nemoudrostí, a rozmlouvali mezi sebou, co by učiniti měli Ježíšovi.',
        12: 'I stalo se v těch dnech, vyšel na horu k modlení. I byl tam přes noc na modlitbě Boží.',
        13: 'A když byl den, povolal učedlníků svých, a vyvolil z nich dvanácte, kteréž i apoštoly nazval:',
        14: '(Šimona, kterémuž také dal jméno Petr, a Ondřeje bratra jeho, Jakuba a Jana, Filipa a Bartoloměje,',
        15: 'Matouše a Tomáše, Jakuba Alfeova, a Šimona, kterýž slove Zelótes,',
        16: 'Judu Jakubova, a Jidáše Iškariotského, kterýž potom byl zrádce.)',
        17: 'I sstoupiv s nimi, stál na místě polním, a zástup učedlníků jeho, a množství veliké lidu ze všeho Judstva i z Jeruzaléma, i z Týru i z Sidonu, kteříž při moři jsou, kteříž byli přišli, aby jej slyšeli, a uzdraveni byli od neduhů svých,',
        18: 'I kteříž trápeni byli od duchů nečistých. A byli uzdravováni.',
        19: 'A všecken zástup hledal se ho dotknouti; nebo moc z něho vycházela, a uzdravovala všecky.',
        20: 'A on pozdvih očí svých na učedlníky, pravil: Blahoslavení chudí, nebo vaše jest království Boží.',
        21: 'Blahoslavení, kteříž nyní lačníte, nebo nasyceni budete. Blahoslavení, kteříž nyní plačete, nebo smáti se budete.',
        22: 'Blahoslavení budete, když vás nenáviděti budou lidé, a když vás vyobcují, a haněti budou, a vyvrhou jméno vaše jako zlé, pro Syna člověka.',
        23: 'Radujte se v ten den, a veselte se, nebo aj, odplata vaše mnohá v nebesích. Takť zajisté činívali prorokům otcové jejich.',
        24: 'Ale běda vám bohatým, nebo vy již máte potěšení své.',
        25: 'Běda vám, kteříž jste nasyceni, nebo lačněti budete. Běda vám, kteříž se nyní smějete, nebo kvíliti a plakati budete.',
        26: 'Běda vám, když by dobře o vás mluvili všickni lidé; nebo tak činívali falešným prorokům otcové jejich.',
        27: 'Ale vámť pravím, kteříž slyšíte: Milujte nepřátely své, dobře čiňte těm, kteříž vás nenávidí,',
        28: 'Dobrořečte těm, kteříž vás proklínají, a modlte se za ty, kteříž vám bezpráví činí.',
        29: 'A udeřil-li by tebe kdo v líce, nasaď mu i druhého, a tomu, kterýž tobě odjímá plášť, také i sukně nebraň.',
        30: 'Každému pak prosícímu tebe dej, a od toho, kterýž béře tvé věci, zase nežádej.',
        31: 'A jakž chcete, aby vám lidé činili, i vy jim též podobně čiňte.',
        32: 'Nebo jestliže milujete ty, kteříž vás milují, jakou míti budete milost? Nebo i hříšníci milují ty, od nichž milováni bývají.',
        33: 'A budete-li dobře činiti těm, kteříž vám dobře činí, jakou máte milost? Však i hříšnící totéž činí.',
        34: 'A budete-li půjčovati těm, od kterýchž se nadějete zase vzíti, jakou máte milost? Však i hříšníci hříšníkům půjčují, aby tolikéž zase vzali.',
        35: 'Nýbrž milujte nepřátely své, a dobře čiňte, a půjčujte, nic se odtud nenadějíce, a budeť odplata vaše mnohá, a budete synové Nejvyššího. Nebo on dobrotivý jest i k nevděčným a zlým.',
        36: 'Protož buďte milosrdní, jako i Otec váš milosrdný jest.',
        37: 'Nesuďte, a nebudete souzeni. Nepotupujte, a nebudete potupeni. Odpouštějte, a budeť vám odpuštěno.',
        38: 'Dávejte, a budeť vám dáno. Míru dobrou, natlačenou, a natřesenou, a osutou dadíť v lůno vaše; touž zajisté měrou, kterouž měříte, bude vám zase odměřeno.',
        39: 'Pověděl jim také i podobenství: Zdali může slepý slepého vésti? Zdaž oba do jámy neupadnou?',
        40: 'Neníť učedlník nad mistra svého, ale dokonalý bude každý, bude-li jako mistr jeho.',
        41: 'Což pak vidíš mrvu v oku bratra svého, a břevna, kteréž jest v tvém vlastním oku, neznamenáš?',
        42: 'Aneb kterak můžeš říci bratru svému: Bratře, nechať vyňmu mrvu, kteráž jest v oku tvém, sám v oku svém břevna nevida? Pokrytče, vyvrz prvé břevno z oka svého, a tehdy prohlédneš, abys vyňal mrvu, kteráž jest v oku bratra tvého.',
        43: 'Neboť není ten strom dobrý, kterýž nese ovoce zlé, aniž jest strom zlý, kterýž nese ovoce dobré.',
        44: 'Každý zajisté strom po svém vlastním ovoci bývá poznán; nebo nezbírají s trní fíků, ani s hloží zbírají hroznů.',
        45: 'Dobrý člověk z dobrého pokladu srdce svého vynáší dobré, a zlý člověk ze zlého pokladu srdce svého vynáší zlé. Nebo z hojnosti srdce mluví ústa jeho.',
        46: 'Co pak mi říkáte: Pane, Pane, a nečiníte, což pravím?',
        47: 'Každý kdož přichází ke mně, a slyší slovo mé, a zachovává je, ukáži vám, komu by podoben byl.',
        48: 'Podoben jest člověku stavějícímu dům, kterýž kopal a vytesal hluboko, a založil grunty v skále. A když se povodeň strhla, obořila se řeka na dům ten, ale nemohla ním pohnouti, nebo byl založen na skále.',
        49: 'Ale kdož slyší a nečiní, podoben jest člověku, kterýž staví dům svůj na zemi bez gruntu. Na kterýž obořila se řeka, a on hned padl, i byl pád domu toho veliký.',
    },
    7: {
        1: 'A když vykonal všecka slova svá při přitomnosti lidu, všel do Kafarnaum.',
        2: 'Setníka pak nějakého služebník nemocen jsa, k smrti se přibližoval, kteréhož on sobě mnoho vážil.',
        3: 'I uslyšav o Ježíšovi, poslal k němu starší Židovské, prose ho, aby přišel a uzdravil služebníka jeho.',
        4: 'A oni přišedše k Ježíšovi, prosili ho snažně, řkouce: Hoden jest, abys mu to učinil.',
        5: 'Nebo miluje národ náš, a školu on nám vystavěl.',
        6: 'Tedy Ježíš šel s nimi. A když již nedaleko byl od domu, poslal k němu ten setník přátely, řka jemu: Pane, nepřidávej sobě práce. (Nejsem zajisté hoden, abys všel pod střechu mou.',
        7: 'A protož jsem i sebe samého za nehodného položil, abych přišel k tobě.) Ale rci slovem, a budeť uzdraven služebník můj.',
        8: 'Nebo i já jsem člověk pod mocí postavený, maje pod sebou žoldnéře, a dím tomuto: Jdi, a jde, a jinému: Přiď, a přijde, a služebníku svému: Učiň toto, a učiní.',
        9: 'Tedy uslyšav to Ježíš, podivil se jemu, a obrátiv se, řekl zástupu, kterýž za ním šel: Pravím vám, že ani v Izraeli nenalezl jsem tak veliké víry.',
        10: 'Vrátivše se pak domů ti, kteříž posláni byli, nalezli služebníka, kterýž nemocen byl, zdravého.',
        11: 'I stalo se potom, šel do města, kteréž slove Naim, a šli s ním učedlníci jeho mnozí a zástup veliký.',
        12: 'A když se přiblížil k bráně města, aj, mrtvý byl nesen ven, syn jediný matky své, a ta vdova byla, a zástup města mnohý s ní.',
        13: 'Kteroužto uzřev Pán, milosrdenstvím hnut jest k ní, a řekl jí: Neplačiž.',
        14: 'A přistoupiv, dotekl se már. (Ti pak, kteříž nesli, zastavili se.) I řekl: Mládenče, toběť pravím, vstaň.',
        15: 'I posadil se ten mrtvý, a počal mluviti. I dal jej mateři jeho.',
        16: 'Tedy podjala všecky bázeň, i velebili Boha, řkouce: Prorok veliký povstal mezi námi, a Bůh navštívil lid svůj.',
        17: 'I vyšla řeč ta o něm po všem Judstvu i po vší okolní krajině.',
        18: 'I zvěstovali Janovi učedlníci jeho o všech těchto věcech. A zavolav kterýchs dvou z učedlníků svých Jan,',
        19: 'Poslal k Ježíšovi, řka: Ty-li jsi ten, kterýž přijíti má, čili jiného čekati máme?',
        20: 'Přišedše pak k němu muži ti, řekli: Jan Křtitel poslal nás k tobě řka: Ty-li jsi ten, kterýž přijíti má, čili jiného čekati máme?',
        21: 'A v touž hodinu mnohé uzdravil od neduhů, od nemocí a duchů zlých, a slepým mnohým zrak dal.',
        22: 'Odpověděv pak Ježíš, řekl jim: Jdouce, povězte Janovi, co jste viděli a slyšeli, že slepí vidí, kulhaví chodí, malomocní očištění přijímají, hluší slyší, mrtví z mrtvých vstávají, chudým se zvěstuje evangelium.',
        23: 'A blahoslavený jest, kdož by se na mně nezhoršil.',
        24: 'A když odešli poslové Janovi, počal praviti zástupům o Janovi: Co jste vyšli na poušť spatřovati? Třtinu-li, kteráž se větrem klátí?',
        25: 'Aneb nač jste hleděti vyšli? Na člověka-li měkkým rouchem oděného? Aj, kteříž v rouše slavném a v rozkoši jsou, v domích královských jsou.',
        26: 'Aneb co jste vyšli viděti? Proroka-li? Jistě pravím vám, i více nežli proroka.',
        27: 'Tentoť jest, o kterémž jest psáno: Aj, já posílám anděla svého před tváří tvou, kterýž připraví cestu tvou před tebou.',
        28: 'Nebo pravím vám, většího proroka mezi syny ženskými nad Jana Křtitele není žádného, ale kdož jest menší v království Božím, většíť jest nežli on.',
        29: 'Tedy všecken lid slyše to i publikáni, velebili Boha, byvše pokřtěni křtem Janovým.',
        30: 'Ale farizeové a zákonníci pohrdli radou Boží sami proti sobě, nebyvše pokřtěni od něho.',
        31: 'I řekl Pán: Komu tedy přirovnám lidi pokolení tohoto, a čemu podobni jsou?',
        32: 'Podobni jsou dětem, kteříž na rynku sedí, a jedni na druhé volají, říkajíce: Pískali jsme vám, a neskákali jste; žalostně jsme naříkali vám, a neplakali jste.',
        33: 'Nebo přišel Jan Křtitel, ani chleba nejeda, ani nepije vína, a pravíte: Ďábelství má.',
        34: 'Přišel Syn člověka, jeda a pije, a pravíte: Aj, člověk žráč a piján vína, přítel publikánů a hříšníků.',
        35: 'Ale ospravedlněna jest moudrost ode všech synů svých.',
        36: 'Prosil ho pak jeden z farizeů, aby jedl s ním. Pročež všed do domu toho farizea, posadil se za stůl.',
        37: 'A aj, žena v městě, kteráž byla hříšnice, zvěděvši, že by seděl za stolem v domě farizea, přinesla nádobu alabastrovou masti.',
        38: 'A stojeci z zadu u noh jeho s pláčem, počala slzami smáčeti nohy jeho, a vlasy hlavy své vytírala, a líbala nohy jeho, a mastí mazala.',
        39: 'Uzřev pak to farizeus, kterýž ho byl pozval, řekl sám v sobě tak: Byť tento byl prorok, vědělť by, která a jaká jest to žena, kteráž se ho dotýká; nebo hříšnice jest.',
        40: 'I odpověděv Ježíš, dí jemu: Šimone, mámť něco povědíti. A on řekl: Mistře, pověz.',
        41: 'Dva dlužníky měl nějaký věřitel. Jeden dlužen byl pět set peněz, a druhý padesát.',
        42: 'A když neměli, odkud by zaplatili, odpustil oběma. Pověziž tedy, který z nich více bude jej milovati?',
        43: 'I odpověděv Šimon, řekl: Mám za to, že ten, kterémuž více odpustil. A on řekl jemu: Právě jsi rozsoudil.',
        44: 'A obrátiv se k ženě, řekl Šimonovi: Vidíš tuto ženu? Všel jsem do domu tvého, vody nohám mým nedal jsi, ale tato slzami smáčela nohy mé, a vlasy hlavy své vytřela.',
        45: 'Nepolíbil jsi mne, ale tato, jakž jsem všel, nepřestala líbati noh mých.',
        46: 'Olejem hlavy mé nepomazal jsi, ale tato mastí mazala nohy mé.',
        47: 'Protož pravím tobě: Odpuštěniť jsou jí hříchové mnozí, neboť milovala mnoho. Komuť se pak málo odpouští, málo miluje.',
        48: 'I řekl jí: Odpuštěniť jsou tobě hříchové.',
        49: 'Tedy počali, kteříž tu spolu seděli za stolem, říci sami mezi sebou: Kdo jest tento, kterýž i hříchy odpouští?',
        50: 'I řekl ženě: Víra tvá tebe k spasení přivedla. Jdiž u pokoji.',
    },
    8: {
        1: 'I stalo se potom, že on chodil po městech a po městečkách, káže a zvěstuje království Boží, a dvanácte s ním.',
        2: 'I ženy některé, kteréž byl uzdravil od duchů zlých a od nemocí: Maria, kteráž slove Magdaléna, z níž bylo sedm ďáblů vyšlo,',
        3: 'A Johanna manželka Chuzova, úředníka Heródesova, a Zuzanna, a jiné mnohé, kteréž posluhovaly jemu z statků svých.',
        4: 'Když se pak scházel zástup mnohý, a z měst hrnuli se k němu, mluvil v podobenství:',
        5: 'Vyšel rozsevač, aby rozsíval símě své. A když on rozsíval, jedno padlo podlé cesty, i pošlapáno jest, a ptáci nebeští zzobali je.',
        6: 'A jiné padlo na skálu, a vzešlé uvadlo, proto že nemělo vláhy.',
        7: 'Jiné pak padlo mezi trní, a spolu zrostlé trní udusilo je.',
        8: 'A jiné padlo v zemi dobrou, a když vzešlo, učinilo užitek stý. To pověděv, volal: Kdo má uši k slyšení, slyš.',
        9: 'I otázali se ho učedlníci jeho, řkouce: Jaké jest to podobenství?',
        10: 'A on řekl: Vám dáno jest znáti tajemství království Božího, ale jiným v podobenství, aby hledíce, neviděli, a slyšíce, nerozuměli.',
        11: 'Jestiť pak podobenství toto: Símě jest slovo Boží.',
        12: 'A kteréž padlo podlé cesty, jsou ti, kteříž slyší, a potom přichází ďábel, a vynímá slovo z srdce jejich, aby nevěříce, spaseni nebyli.',
        13: 'Ale kteříž na skálu, ti když slyší, s radostí přijímají slovo, ale ti kořenů nemají; ti na čas věří, a v čas pokušení odstupují.',
        14: 'Kteréž pak mezi trní padlo, tiť jsou, kteříž slyší, ale po pečování a zboží a rozkošech života jdouce, bývají udušeni, a nepřinášejí užitku.',
        15: 'Ale kteréž v zemi dobrou, ti jsou, kteříž v srdci ctném a dobrém, slyšíce slovo, zachovávají, a užitek přinášejí v trpělivosti.',
        16: 'Žádný pak rozsvítě svíci, nepřikrývá jí nádobou, ani staví pod postel, ale na svícen staví, aby ti, kteříž vcházejí, světlo viděli.',
        17: 'Nebo nic není tajného, což by nemělo býti zjeveno, ani co ukrytého, což by nemělo poznáno býti, a na světlo vyjíti.',
        18: 'Protož vizte, jak slyšíte. Nebo kdož má, tomu bude dáno, a kdo nemá, i to, což domnívá se míti, bude odjato od něho.',
        19: 'Tedy přišli k němu matka a bratří jeho, ale nemohli ho dojíti pro zástup.',
        20: 'I pověděli mu, řkouce: Matka tvá a bratří tvoji stojí vně, chtíce tebe viděti.',
        21: 'A on odpověděv, řekl jim: Matka má a bratří moji jsou ti, kteříž slovo Boží slyší a plní je.',
        22: 'Stalo se pak v jeden den, že on vstoupil na lodí i učedlníci jeho. I řekl jim: Přeplavme se přes jezero. I pustili se.',
        23: 'A když se plavili, usnul. Tedy přišel vítr bouřlivý na jezero, a lodí se naplňovala, tak že v nebezpečenství byli.',
        24: 'I přistoupivše, zbudili ho, řkouce: Mistře, Mistře, hyneme. A on procítiv, přimluvil větru a zdutí vod. I spokojili se, a stalo se utišení.',
        25: 'I řekl jim: Kdež jest víra vaše? Kteřížto bojíce se, podivili se, vespolek řkouce: I kdo jest tento, že i větrům přikazuje i vodám, a poslouchají ho?',
        26: 'I přeplavili se do krajiny Gadarenské, kteráž jest proti Galilei.',
        27: 'A když vystoupil na zemi, potkal jej muž nějaký z města, kterýž měl ďábelství od mnoha časů, a rouchem se neodíval, ani v domě nebýval, ale v hrobích.',
        28: 'Uzřev pak Ježíše a zkřikna, padl před ním, a hlasem velikým řekl: Co jest tobě do mne, Ježíši, Synu Boha nejvyššího? Prosím tebe, netrap mne.',
        29: 'Nebo přikazoval tomu duchu nečistému, aby vyšel z toho člověka. Po mnohé zajisté časy jím lomcoval, tak že býval ukován řetězy, a v poutech ostříhán, ale on polámaje okovy, býval od ďábelství puzen na poušť.',
        30: 'I otázal se ho Ježíš, řka: Jakť říkají? A on řekl: Množství. Nebo bylo mnoho ďáblů vešlo do něho.',
        31: 'Tedy prosili ho, aby jim nepřikazoval odtud odjíti do propasti.',
        32: 'Bylo pak tu veliké stádo vepřů, kteříž se pásli na hoře. I prosili ho, aby jim dopustil do nich vjíti. I dopustil jim.',
        33: 'I vyšedše ďáblové z toho člověka, vešli do vepřů, i hnalo se to stádo prudce s vrchu do jezera, a ztonulo.',
        34: 'A viděvše pastýři, co se stalo, utekli, a šedše, vypravovali to v městě i po vsech.',
        35: 'I vyšli, aby viděli, co se stalo. I přišli k Ježíšovi, a nalezli člověka toho, z kteréhož ďáblové vyšli, oděného a majícího rozum, an sedí u noh Ježíšových. I báli se.',
        36: 'A vypravovali jim také ti, kteříž byli viděli, kterak jest ten vyproštěn, kterýž ďábelství měl.',
        37: 'I prosilo ho všecko množství té okolní krajiny Gadarenských, aby odšel od nich; nebo bázní velikou naplněni byli. A on vstoupiv na lodí, navrátil se.',
        38: 'Prosil ho pak muž ten, z kteréhož ďáblové vyšli, aby s ním byl. Ale Ježíš propustil ho, řka:',
        39: 'Navrať se do domu svého, a vypravuj, kterak veliké věci učinil tobě Bůh. I odšel, po všem městě vypravuje, jak veliké věci učinil jemu Ježíš.',
        40: 'Stalo se pak, když se navrátil Ježíš, že přijal jej zástup; nebo všickni očekávali ho.',
        41: 'A aj, přišel muž, kterémuž jméno bylo Jairus, a ten byl kníže školy. I padna k nohám Ježíšovým, prosil ho, aby všel do domu jeho.',
        42: 'Nebo měl dceru jedinou, asi ve dvanácti letech, a ta umírala. A když šel, tiskli jej zástupové.',
        43: 'Tedy žena, kteráž nemoc svou trpěla od let dvanácti, a byla na lékaře vynaložila všecken statek, a od žádného nemohla uzdravena býti,',
        44: 'Přistoupivši po zadu, dotkla se podolka roucha jeho, a hned přestala nemoc její.',
        45: 'I řekl Ježíš: Kdo jest, ješto se mne dotekl? A když všickni zapírali, řekl Petr, a kteříž s ním byli: Mistře, zástupové tebe tisknou a tlačí, a pravíš: Kdo se mne dotekl?',
        46: 'I řekl Ježíš: Dotekl se mne někdo, nebo poznal jsem já, že moc ode mne vyšla.',
        47: 'A viduci ta žena, že by tajno nebylo, třesuci se, přistoupila a padla před ním, a pro kterou příčinu dotkla se ho, pověděla jemu přede vším lidem, a kterak jest hned uzdravena.',
        48: 'A on řekl jí: Dobré mysli buď, dcero, víra tvá tebe uzdravila. Jdiž u pokoji.',
        49: 'A když on ještě mluvil, přišel jeden od knížete školy, řka jemu: Umřela dcera tvá, nezaměstknávej Mistra.',
        50: 'Ale Ježíš uslyšav to, odpověděl jemu: Neboj se, věř toliko, a zdrávať bude.',
        51: 'A všed do domu, nedopustil s sebou vjíti žádnému, než Petrovi a Jakubovi a Janovi, a otci a mateři té děvečky.',
        52: 'Plakali jí pak všickni a kvílili. A on řekl: Neplačtež. Neumřelať, ale spí.',
        53: 'I posmívali se jemu, vědouce, že umřela.',
        54: 'On pak vyhnav ven všecky, a ujav ruku její, zvolal, řka: Děvečko, vstaň.',
        55: 'I navrátil se duch její, a vstala hned. I kázal jí dáti jísti.',
        56: 'I divili se náramně rodičové její. A on jim kázal, aby žádnému nepravili o tom, co se bylo stalo.',
    },
    9: {
        1: 'I svolav dvanácte učedlníků svých, dal jim sílu a moc nad všelikým ďábelstvím, a aby neduhy uzdravovali.',
        2: 'I poslal je, aby kázali království Boží, a uzdravovali nemocné.',
        3: 'A řekl jim: Nic nebeřte na tu cestu, ani hůlky, ani mošny, ani chleba, ani peněz, ani po dvou sukních mívejte.',
        4: 'A do kteréhožkoli domu vešli byste, tu zůstaňte, a odtud vyjděte.',
        5: 'A kteříž by vás koli nepřijali, vyjdouce z města toho, také i ten prach z noh svých vyrazte na svědectví proti nim.',
        6: 'I vyšedše, chodili po městečkách vůkol, zvěstujíce evangelium, a uzdravujíce všudy.',
        7: 'Uslyšel pak Heródes čtvrták o všech věcech, kteréž se dály od něho. I rozjímal to v mysli své, proto že bylo praveno od některých, že by Jan vstal z mrtvých,',
        8: 'A od jiných, že by se Eliáš zjevil, od některých pak, že by jeden z proroků starých vstal.',
        9: 'I řekl Heródes: Jana jsem já sťal. Kdož pak jest tento, o kterémž já slyším takové věci? I žádostiv byl ho viděti.',
        10: 'Vrátivše se pak apoštolé, vypravovali jemu, cožkoli činili. A pojav je, odšel soukromí na místo pusté města řečeného Betsaida.',
        11: 'Zvěděvše pak zástupové, šli za ním; i přijal je, a mluvil jim o království Božím, a ty, kteříž uzdravení potřebovali, uzdravoval.',
        12: 'Den pak počal se nachylovati. I přistoupivše dvanácte, řekli jemu: Propusť zástupy, ať rozejdouce se do městeček okolních a do vesnic, jdou a hledají pokrmů, nebo jsme tuto na místě pustém.',
        13: 'I řekl jim: Dejte vy jim jísti. A oni řekli: Nemámeť víc než pět chlebů a dvě rybě, leč bychom my snad šli a nakoupili na tento všecken lid pokrmů?',
        14: 'Nebo bylo mužů okolo pěti tisíců. I řekl učedlníkům svým. Rozkažte se jim posaditi v každém řadu po padesáti.',
        15: 'I učinili tak, a posadili se všickni.',
        16: 'A vzav těch pět chlebů a ty dvě rybě, vzhlédl v nebe, a dobrořečil jim, i lámal, a rozdával učedlníkům, aby kladli před zástup.',
        17: 'I jedli, a nasyceni jsou všickni. A sebráno jest, což jim bylo ostalo drobtů, dvanácte košů.',
        18: 'I stalo se, když se on modlil obzvláštně, že byli s ním učedlníci. I otázal se jich, řka: Kým mne praví býti zástupové?',
        19: 'A oni odpověděvše, řekli: Janem Křtitelem, a jiní Eliášem, jiní pak, že prorok jeden z starých vstal.',
        20: 'I řekl jim: Vy pak kým mne býti pravíte? Odpověděv Petr, řekl: Krista toho Božího.',
        21: 'A on s pohrůžkou jim přikázal, aby toho žádnému nepravili,',
        22: 'Pravě: Že Syn člověka musí mnoho trpěti, a potupen býti od starších a od předních kněží {biskupů} i od zákonníků, a zamordován býti, a třetího dne z mrtvých vstáti.',
        23: 'I pravil všechněm: Chce-li kdo přijíti za mnou, zapři sám sebe, a beř svůj kříž na každý den, a následuj mne.',
        24: 'Nebo kdož bude chtíti duši svou zachovati, ztratíť ji; a kdož ztratí duši svou pro mne, tenť ji zachová,',
        25: 'Nebo co jest platno člověku, by všecken svět získal, kdyby sám sebe ztratil, aneb sám sebe zmrhal?',
        26: 'Nebo kdož by se za mne styděl a za mé řeči, za tohoť se Syn člověka styděti bude, když přijde v slávě své a Otcově i svatých andělů.',
        27: 'Ale pravímť vám jistě: Jsou někteří z stojících tuto, kteříž neokusí smrti, až uzří království Boží.',
        28: 'I stalo se po těch řečech, jako po osmi dnech, že vzav s sebou Petra a Jakuba a Jana, vstoupil na horu, aby se modlil.',
        29: 'A když se modlil, učiněna jest tvář jeho proměněná, a oděv jeho bílý a stkvoucí.',
        30: 'A aj, dva muži mluvili s ním, a ti byli Mojžíš a Eliáš.',
        31: 'Kteříž okázavše se v slávě, vypravovali o smrti jeho, kterouž měl podstoupiti v Jeruzalémě.',
        32: 'Petr pak a ti, kteříž s ním byli, obtíženi byli snem, a procítivše, viděli slávu jeho a ty dva muže, ani stojí s ním.',
        33: 'I stalo se, když oni odešli od něho, řekl Petr Ježíšovi: Mistře, dobréť jest nám zde býti. Protož udělejme tři stánky, tobě jeden, a Mojžíšovi jeden, a Eliášovi jeden, nevěda, co mluví.',
        34: 'A když on to mluvil, stal se oblak, i zastínil je. Báli se pak, když onino vcházeli do oblaku.',
        35: 'I stal se hlas z oblaku řkoucí: Tentoť jest ten Syn můj milý, toho poslouchejte.',
        36: 'A když se ten hlas stal, nalezen jest Ježíš sám. A oni mlčeli, a nepravili žádnému v těch dnech ničeho z těch věcí, kteréž viděli.',
        37: 'Stalo se pak druhého dne, když sstupovali s hory, potkal jej zástup mnohý.',
        38: 'A aj, muž z zástupu zvolal, řka: Mistře, prosím tebe, vzhlédni na syna mého, neboť jediného toho mám.',
        39: 'A aj, duch jej napadá, a on i hned křičí, a lomcuje jím slinícím se, a nesnadně odchází od něho, sápaje jím.',
        40: 'I prosil jsem učedlníků tvých, aby jej vyvrhli, ale nemohli.',
        41: 'I odpověděv Ježíš, řekl: Ó pokolení nevěrné a převrácené, dokudž budu u vás, a snášeti budu vás? Přiveď sem syna svého.',
        42: 'A v tom, když on přicházel, porazil jej ďábel, a lomcoval jím. I přimluvil duchu nečistému Ježíš, a uzdravil toho mládence, a navrátil jej otci jeho.',
        43: 'I děsili se všickni nad velikomocností Božskou. A když se všickni divili všem věcem, kteréž činil Ježíš, řekl učedlníkům svým:',
        44: 'Složte vy v uších svých řeči tyto, neboť Syn člověka bude vydán v ruce lidské.',
        45: 'Ale oni nesrozuměli slovu tomu, a bylo před nimi skryto, aby nevyrozuměli jemu. A nesměli se ho otázati o tom slovu.',
        46: 'I vznikla mezi nimi hádka o to, kdo by z nich byl největší.',
        47: 'Ježíš pak viděv přemyšlování srdce jejich, vzav dítě, postavil je podlé sebe,',
        48: 'A řekl jim: Kdožkoli přijal by dítě toto ve jménu mém, mneť přijímá; a kdož by koli mne přijal, přijímá toho, kterýž mne poslal. Nebo kdožť jest nejmenší mezi všemi vámi, tenť bude veliký.',
        49: 'I odpověděv Jan, řekl: Mistře, viděli jsme jednoho, an ve jménu tvém ďábly vymítá; i bránili jsme mu, proto že nechodí s námi.',
        50: 'I dí jemu Ježíš: Nebraňtež. Nebo kdoť není proti nám, s námiť jest.',
        51: 'I stalo se, když se doplnili dnové vzetí jeho zhůru, že on se na tom ustavil, aby šel do Jeruzaléma.',
        52: 'I poslal posly před sebou. A oni jdouce, vešli do městečka Samaritánského, aby jemu připravili.',
        53: 'Ale nepřijali ho, proto že oblíčej jeho byl obrácen k jití do Jeruzaléma.',
        54: 'A viděvše to učedlníci jeho Jakub a Jan, řekli: Pane, chceš-li, ať díme, aby oheň sstoupil s nebe, a spálil je, jako i Eliáš učinil?',
        55: 'Ale obrátiv se, potrestal jich, řka: Nevíte, čího jste vy duchu.',
        56: 'Syn zajisté člověka nepřišel zatracovati duší lidských, ale aby spasil. I odešli do jiného městečka.',
        57: 'Stalo se pak, když šli, že řekl jemu na cestě jeden: Pane, půjdu za tebou, kam se koli obrátíš.',
        58: 'I řekl jemu Ježíš: Lišky doupata mají, a ptáci nebeští hnízda, ale Syn člověka nemá, kde by hlavu sklonil.',
        59: 'I řekl jinému: Poď za mnou. Ale on řekl: Pane, dopusť mi prvé jíti a pochovati otce mého.',
        60: 'I dí jemu Ježíš: Nech ať mrtví pochovávají mrtvé své, ale ty jda, zvěstuj království Boží.',
        61: 'I řekl opět jiný: Půjdu za tebou, Pane, ale prvé dopusť mi, ať se rozžehnám s těmi, kteříž jsou v domě mém.',
        62: 'Řekl jemu Ježíš: Žádný, kdož vztáhna ruku svou k pluhu, ohlídal by se nazpět, není způsobný k království Božímu.',
    },
    10: {
        1: 'Potom pak vyvolil Pán i jiných sedmdesát, a poslal je po dvou před tváří svou do každého města i místa, kamž měl sám přijíti.',
        2: 'A pravil jim: Žeň zajisté jest mnohá, ale dělníků málo. Protož proste Pána žně, ať vypudí dělníky na žeň svou.',
        3: 'Jdětež. Aj, já posílám vás jako berany mezi vlky.',
        4: 'Nenostež pytlíka, ani mošny, ani obuvi, a žádného na cestě nepozdravujte.',
        5: 'A do kteréhožkoli domu vejdete, nejprvé rcete: Pokoj tomuto domu.',
        6: 'A bude-liť tu syn pokoje, odpočineť na něm pokoj váš; pakli nic, k vámť se navrátí.',
        7: 'A v témž domu ostaňte, jedouce a pijíce, což u nich jest, nebo hoden jest dělník mzdy své. Nechoďtež z domu do domu.',
        8: 'Ale do kteréhožkoli města vešli byste, a přijali by vás, jezte, což před vás předloží.',
        9: 'A uzdravujte nemocné, kteříž by v něm byli, a rcete jim: Přiblížiloť se k vám království Boží.',
        10: 'A do kteréhožkoli města vešli byste, a nepřijali by vás, vyjdouce na ulice jeho, rcetež:',
        11: 'Také i ten prach, kterýž se přichytil nás z města vašeho, vyrážíme na vás. Ale však to vězte, žeť se jest přiblížilo k vám království Boží.',
        12: 'Pravím zajisté vám, že Sodomským v onen den lehčeji bude než tomu městu.',
        13: 'Běda tobě Korozaim, běda tobě Betsaido. Nebo kdyby v Týru a v Sidonu činěni byli divové ti, kteříž v vás činěni jsou, dávno by v žíni a v popele sedíce, pokání činili.',
        14: 'A protož Týru a Sidonu lehčeji bude na soudu nežli vám.',
        15: 'A ty Kafarnaum, kteréž jsi až do nebe zvýšeno, až do pekla sníženo budeš.',
        16: 'Kdož vás slyší, mne slyší; a kdo vámi pohrdá, mnou pohrdá; kdož pak mnou pohrdá, pohrdáť tím, kdož mne poslal.',
        17: 'Potom navrátilo se s radostí těch sedmdesáte, řkouce: Pane, také i ďáblové se nám poddávají ve jménu tvém.',
        18: 'I řekl jim: Viděl jsem satana jako blesk padajícího s nebe.',
        19: 'Aj, dávámť vám moc šlapati na hady a na štíry i na všelikou moc nepřítele, a nic vám neuškodí.',
        20: 'A však z toho se neradujte, že se vám poddávají duchové, ale raději se radujte, že jména vaše napsána jsou v nebesích.',
        21: 'V tu hodinu rozveselil se v duchu Ježíš, a řekl: Chválím tě, Otče, Pane nebe i země, že jsi tyto věci skryl před moudrými a opatrnými, a zjevils je nemluvňátkům. Ovšem, Otče, nebo se tak líbilo před tebou.',
        22: 'Všecky věci dány jsou mi od Otce mého, a žádný neví, kdo by byl Syn, jediné Otec, a kdo by byl Otec, jediné Syn, a komuž by chtěl Syn zjeviti.',
        23: 'A obrátiv se k učedlníkům obzvláštně, řekl: Blahoslavené oči, kteréž vidí, co vy vidíte.',
        24: 'Nebo pravím vám, že mnozí proroci i králové chtěli viděti, což vy vidíte, ale neviděli, a slyšeti, což vy slyšíte, ale neslyšeli.',
        25: 'A aj, jeden zákonník vstal, pokoušeje ho, a řka: Mistře, co čině, život věčný dědičně obdržím?',
        26: 'A on řekl jemu: V zákoně co jest psáno? Kterak čteš?',
        27: 'A on odpověděv, řekl: Milovati budeš Pána Boha svého ze všeho srdce svého, a ze vší duše své, a ze vší síly své, i ze vší mysli své, a bližního svého jako sebe samého.',
        28: 'I řekl mu: Právě jsi odpověděl. To čiň, a živ budeš.',
        29: 'On pak chtěje se sám ospravedlniti, dí Ježíšovi: A kdo jest můj bližní?',
        30: 'I odpověděv Ježíš, řekl: Člověk jeden šel z Jeruzaléma do Jericho, i upadl mezi lotry. Kteříž obloupivše jej a zranivše, odešli, odpolu živého nechavše.',
        31: 'I přihodilo se, že kněz jeden šel touž cestou, a uzřev jej, pominul.',
        32: 'Též i Levíta přišed až k tomu místu, a uzřev jej, pominul.',
        33: 'Samaritán pak jeden, cestou se ubíraje, přišel až k němu, a uzřev jej, milosrdenstvím hnut jest.',
        34: 'A přistoupiv, uvázal rány jeho, naliv oleje a vína, a vloživ jej na hovado své, vedl do hospody, a péči o něj měl.',
        35: 'Druhého pak dne odjíti maje, vyňav dva peníze, dal hospodáři, a řekl jemu: Měj o něj péči, a cožkoli nad to vynaložíš, já když se vrátím, zaplatím tobě.',
        36: 'Kdo tedy z těch tří zdá se tobě bližním býti tomu, kterýž upadl mezi lotry?',
        37: 'A on řekl: Ten, kterýž prokázal milosrdenství nad ním. I řekl jemu Ježíš: Jdi, i ty učiň též.',
        38: 'I stalo se, když šli, že on všel do jednoho městečka. Žena pak jedna, jménem Marta, přijala jej do domu svého.',
        39: 'A ta měla sestru, jménem Marii, kteráž seděci u noh Ježíšových, poslouchala slova jeho.',
        40: 'Ale Marta pečlivá byla při mnohé službě. Kteráž přistoupivši, řekla: Pane, nemáš-liž o to péče, že sestra má nechala mne samé sloužiti? Protož rci jí, ať mi pomůž.',
        41: 'A odpověděv, řekl jí Ježíš: Marta, Marta, pečlivá jsi, a rmoutíš se při mnohých věcech.',
        42: 'Ale jednohoť jest potřebí. Mariať dobrou stránku vyvolila, kteráž nebude odjata od ní.',
    },
    11: {
        1: 'I stalo se, když se na jednom místě modlil, když přestal, řekl jemu jeden z učedlníků jeho: Pane, nauč nás modliti se, jako i Jan učil učedlníky své.',
        2: 'I řekl jim: Když se modlíte, říkejte: Otče náš, kterýž jsi v nebesích, posvěť se jméno tvé. Přiď království tvé. Buď vůle tvá, jako v nebi tak i na zemi.',
        3: 'Chléb náš vezdejší dávej nám každého dne.',
        4: 'I odpusť nám hříchy naše, nebo i my odpouštíme všelikému vinníku svému. A neuvoď nás v pokušení, ale zbav nás od zlého.',
        5: 'I řekl jim: Kdo z vás bude míti přítele, a půjde k němu o půlnoci, a dí jemu: Příteli, půjč mi tří chlebů.',
        6: 'Nebo přítel můj přišel s cesty ke mně, a nemám, co bych předložil před něj.',
        7: 'A on vnitř jsa, odpověděl by: Nečiň mi nevole; dvéře již zavříny, a dítky mé se mnou jsou v pokoji. Nemohuť vstáti a dáti tobě.',
        8: 'Pravím vám: Ačť nedá jemu, vstana, proto že jest přítel jeho, ale však pro nezbednost jeho vstana, dá jemu, kolikžkoli potřebuje.',
        9: 'I jáť pravím vám: Proste, a budeť vám dáno; hledejte, a naleznete; tlucte, a budeť vám otevříno.',
        10: 'Nebo každý, kdož prosí, béře; a kdož hledá, nalézá; a tomu, kdož tluče, bude otevříno.',
        11: 'Kterého pak z vás otce prosil by syn za chléb, zdali kamene podá jemu? Aneb za rybu, zdali místo ryby dá jemu hada?',
        12: 'Aneb prosil-li by za vejce, zdali podá jemu štíra?',
        13: 'Poněvadž tedy vy, jsouce zlí, umíte dobré dary dávati dětem svým, čím více Otec váš nebeský dá Ducha svatého těm, kteříž ho prosí?',
        14: 'I vymítal ďábelství, a to bylo němé. Stalo se pak, když vyšlo ďábelství, mluvil ten němý. I divili se zástupové.',
        15: 'Ale někteří z nich pravili: Skrze Belzebuba, kníže ďábelské, vymítá ďábly.',
        16: 'A jiní pokoušejíce, znamení od něho hledali s nebe.',
        17: 'Ale on znaje myšlení jejich, řekl jim: Každé království samo v sobě rozdělené pustne, i dům rozdvojený padá.',
        18: 'Jestližeť jest pak i satan proti sobě rozdělen, kterakž stane království jeho? Nebo pravíte, že já skrze Belzebuba vymítám ďábly.',
        19: 'Jestliže já skrze Belzebuba vymítám ďábly, synové vaši skrze koho vymítají? Protož oni soudcové vaši budou.',
        20: 'Pakliť prstem Božím vymítám ďábly, jistěť přišlo k vám království Boží.',
        21: 'Když silný oděnec ostříhá síně své, v pokoji jsou všecky věci, kteréž má.',
        22: 'Pakli by silnější než on přijda, přemohl jej, všecka odění jeho odejme, v něž úfal, a loupeže jeho rozdělí.',
        23: 'Kdož není se mnou, proti mně jest; a kdož neshromažďuje se mnou, rozptylujeť.',
        24: 'Když nečistý duch vyjde od člověka, chodí po místech suchých, hledaje odpočinutí. A nenalezna, dí: Vrátím se do domu svého, odkudž jsem vyšel.',
        25: 'A přijda, nalezne vymetený a ozdobený.',
        26: 'Tehdy jde, a přijme k sobě jiných sedm duchů horších, než jest sám, a vejdouce, přebývají tam. I jsou poslední věci člověka toho horší nežli první.',
        27: 'I stalo se, když on to mluvil, že pozdvihši hlasu jedna žena z zástupu, řekla jemu: Blahoslavený život, kterýž tebe nosil, a prsy, kterýchž jsi požíval.',
        28: 'On pak řekl: Anobrž blahoslavení, kteříž slyší slovo Boží, a ostříhají jeho.',
        29: 'A když se zástupové scházeli k němu, počal praviti: Pokolení toto nešlechetné jest. Znamení vyhledává, ale znamení jemu nebude dáno, než znamení to Jonáše proroka.',
        30: 'Nebo jakož Jonáš učiněn byl znamením Ninivitským, takť bude i Syn člověka pokolení tomuto.',
        31: 'Královna od poledne stane na soudu s muži pokolení tohoto, a odsoudí je. Nebo přijela od končin země, aby slyšela moudrost Šalomounovu, a aj, více než Šalomoun tuto.',
        32: 'Muži Ninivitští povstanou na soudu s pokolením tímto, a odsoudí je. Nebo činili pokání k kázaní Jonášovu, a aj, více nežli Jonáš tuto.',
        33: 'Žádný rozsvítě svíci, nepostaví jí do skrýše, ani pod kbelec, ale na svícen, aby ti, kteříž vcházejí, světlo viděli.',
        34: 'Svíce těla jest oko. Když by tedy oko tvé sprostné bylo, i tělo tvé všecko bude světlé; a pakliť bude nešlechetné, i tělo tvé tmavé bude.',
        35: 'Viziž tedy, aby světlo, kteréž jest v tobě, nebylo tmou.',
        36: 'Pakli celé tělo tvé světlé bude, nemaje žádné částky tmavé, budeť všecko tak světlé, že tě jako svíce bleskem osvítí.',
        37: 'A když on mluvil, prosil ho jeden farizeus, aby obědval u něho. A všed, posadil se za stůl.',
        38: 'Farizeus pak viděv to, podivil se, že se neumyl před obědem.',
        39: 'I řekl Pán jemu: Nyní vy farizeové povrchu konvice a misy čistíte, ale to, což vnitř jest u vás, plno jest loupeže a nešlechetnosti.',
        40: 'Blázni, zdaliž ten, kterýž učinil, což zevnitř jest, neučinil také i toho, což jest vnitř?',
        41: 'Ale však i z toho, což máte, dávejte almužnu, a aj, všecky věci vaše čisté budou.',
        42: 'Ale běda vám farizeům, že desátky dáváte z máty a z routy a ze všeliké byliny, ale opouštíte soud a lásku Boží. Tyto věci měli jste činiti, a oněch neopouštěti.',
        43: 'Běda vám farizeům, nebo milujete první místa v školách a pozdravování na trzích.',
        44: 'Běda vám, zákonníci a farizeové pokrytci, nebo jste jako hrobové nepatrní, a lidé chodíce po nich, nevědí.',
        45: 'I odpověděv jeden z zákonníků, řekl jemu: Mistře, tyto věci mluvě, i nám také lehkost činíš.',
        46: 'A on řekl: I vám zákonníkům běda, nebo obtěžujete lidi břemeny nesnesitelnými, a sami se těch břemen jedním prstem nedotýkáte.',
        47: 'Běda vám, proto že vzděláváte hroby prorocké, kteréž otcové vaši zmordovali.',
        48: 'A tak osvědčujete a potvrzujete skutků otců svých. Nebo oni zajisté zmordovali je, vy pak vzděláváte hroby jejich.',
        49: 'Protož i Moudrost Boží řekla: Pošliť k nim proroky a apoštoly, a z těch některé mordovati budou, a jiné vyháněti,',
        50: 'Aby požádáno bylo od tohoto pokolení krve všech proroků, kteráž vylita jest od ustanovení světa,',
        51: 'Od krve Abelovy až do krve Zachariášovy, kterýž zahynul mezi oltářem a chrámem. Jistě, pravím vám, požádáno jí bude od pokolení tohoto.',
        52: 'Běda vám zákonníkům, nebo jste vzali klíč umění; sami jste nevešli, a těm, kteříž vcházeli, zbránili jste.',
        53: 'A když jim to mluvil, počali zákonníci a farizeové přísně na něj dotírati, a k mnohým řečem příčiny jemu dávati.',
        54: 'Úklady činíce jemu, a hledajíce popadnouti něco z úst jeho, aby jej obžalovali.',
    },
    12: {
        1: 'A v tom, když se na tisíce lidu sešlo, tak že jedni druhé velmi tlačili, počal mluviti k učedlníkům svým: Nejpředněji se varujte od kvasu farizeů, kterýž jest pokrytství.',
        2: 'Neboť nic není skrytého, což by nemělo býti zjeveno; aniž jest co tajného, ješto by nemělo býti zvědíno.',
        3: 'Protož to, co jste pravili ve tmách, bude na světle slyšáno, a co jste v uši šeptali v pokojích, hlásánoť bude na střechách.',
        4: 'Pravím pak vám přátelům svým: Nestrachujte se těch, kteříž tělo zabíjejí, a potom nemají, co by více učinili.',
        5: 'Ale ukážiť vám, koho se máte báti: Bojte se toho, kterýž, když zabije, má moc uvrci do pekelného ohně. Jistě pravím vám, toho se bojte.',
        6: 'Zdaliž nebývá pět vrabečků prodáváno za dva penížky? A jeden z nich není v zapomenutí před Bohem.',
        7: 'Nýbrž i vlasové hlavy vaší všickni v počtu jsou. Protož nebojtež se, mnohoť vy vrabečků převyšujete.',
        8: 'Pravímť pak vám: Každý kdož by koli vyznal mne před lidmi, i Syn člověka vyzná jej před anděly Božími.',
        9: 'Kdož by mne pak zapřel před lidmi, zapřínť bude před anděly Božími.',
        10: 'A každý kdož dí slovo proti Synu člověka, bude mu odpuštěno, ale tomu, kdož by se Duchu svatému rouhal, nebudeť odpuštěno.',
        11: 'Když pak vás voditi budou do škol a k vládařům a k mocným, nepečujte, kterak aneb co byste odpovídali, aneb co byste mluvili.',
        12: 'Duch svatý zajisté naučí vás v tu hodinu, co byste měli mluviti.',
        13: 'I řekl jemu jeden z zástupu: Mistře, rci bratru mému, ať rozdělí se mnou dědictví.',
        14: 'A on řekl jemu: Člověče, kdo mne ustavil soudcím aneb děličem nad vámi?',
        15: 'I řekl jim: Viztež a vystříhejte se od lakomství; neboť ne v rozhojnění statku něčího život jeho záleží.',
        16: 'Pověděl pak jim podobenství, řka: Člověka jednoho bohatého hojné úrody pole přineslo.',
        17: 'I přemyšloval sám v sobě, řka: Co učiním? Nebo nemám, kde bych shromáždil úrody své.',
        18: 'I řekl: Toto učiním: Zbořím stodoly své, a větších nastavím, a tu shromáždím všecky své úrody i zboží svá.',
        19: 'A dím duši své: Duše, máš mnoho statku složeného za mnohá léta, odpočívej, jez, pí, měj dobrou vůli.',
        20: 'I řekl jemu Bůh: Ó blázne, této noci požádají duše tvé od tebe, a to, cožs připravil, čí bude?',
        21: 'Takť jest, kdož sobě poklady shromažďuje, a není v Bohu bohatý.',
        22: 'Řekl pak učedlníkům svým: Protož pravím vám: Nebuďte pečliví o život svůj, co byste jedli, ani o tělo, čím byste se odívali.',
        23: 'Život více jest nežli pokrm, i tělo nežli oděv.',
        24: 'Patřte na havrany, žeť nesejí, ani nežnou, a nemají špižírny {pivnice}, ani stodoly a však Bůh živí je. I čím v větší vážnosti jste vy než ptactvo?',
        25: 'A kdož pak z vás pečlivě mysle, můž přidati ku postavě své loket jeden?',
        26: 'Poněvadž tedy nemůžete s to býti, což nejmenšího jest, proč se o jiné věci staráte?',
        27: 'Patřte na kvítí, kterak rostou, nedělají, ani předou, pravímť pak vám, že ani Šalomoun ve vší slávě své nebyl tak odín, jako jedno z těchto.',
        28: 'A poněvadž trávu, kteráž dnes na poli jest, a zítra do peci uvržena bývá, Bůh tak odívá, čím více vás, ó malé víry?',
        29: 'I vy nehledejtež toho, co byste jedli, aneb co byste pili, aniž o to roztržité mysli buďte.',
        30: 'Nebo těch všech věcí národové světa tohoto hledají, Otec pak váš ví, že těch věcí potřebujete.',
        31: 'Ale raději hledejte království Božího, a tyto všecky věci budou vám přidány.',
        32: 'Neboj se, ó maličké stádce, neboť se zalíbilo Otci vašemu dáti vám království.',
        33: 'Prodávejte statky své, a dávejte almužnu. Dělejte sobě pytlíky, kteříž nevetšejí, poklad, kterýž nehyne v nebesích, kdež zloděj dojíti nemůž, aniž mol kazí.',
        34: 'Nebo kdež jest poklad váš, tuť bude i srdce vaše.',
        35: 'Buďtež bedra vaše přepásaná, a svíce hořící.',
        36: 'A vy podobni lidem očekávajícím Pána svého, až by se vrátil z svadby, aby hned, jakž by přišel a potloukl, otevřeli jemu.',
        37: 'Blaze služebníkům těm, kteréž přijda Pán, nalezl by, a oni bdí. Amen pravím vám, že přepáše se, a vsadí je za stůl, a chodě, bude jim sloužiti.',
        38: 'A přišel-liť by v druhé bdění, a pakliť by v třetím bdění přišel, a tak je nalezl, blahoslavení jsou ti služebníci,',
        39: 'Toto pak vězte, že byť věděl hospodář, v kterou by hodinu měl zloděj přijíti, bděl by zajisté, a nedal by podkopati domu svého.',
        40: 'Protož i vy buďte hotovi, nebo v kterou hodinu nenadějete se, Syn člověka přijde.',
        41: 'I řekl jemu Petr: Pane, nám-li pravíš toto podobenství, čili všechněm?',
        42: 'I dí Pán: Kdo jest věrný šafář a opatrný, jehož by ustanovil pán nad čeledí svou, aby jim v čas dával vyměřený pokrm?',
        43: 'Blahoslavený služebník ten, kteréhož, když by přišel pán jeho, nalezne, an tak činí.',
        44: 'V pravdě pravím vám, že nade vším statkem svým ustanoví jej.',
        45: 'Pakli by řekl služebník ten v srdci svém: Prodlévá přijíti pán můj, i počal by bíti služebníky a děvky, a jísti a píti i opíjeti se:',
        46: 'Přijdeť pán služebníka toho v den, v kterýž se nenaděje, a v hodinu, kteréž neví. I oddělíť jej, a díl jeho položí s nevěrnými.',
        47: 'Služebník pak ten, kterýž by znal vůli pána svého, a nebyl hotov, a nečinil podlé vůle jeho, bit bude velmi.',
        48: 'Ale kterýž neznal, a činil hodné věci trestání, bit bude méně. Každému pak, komuž jest mnoho dáno, mnoho bude od něho požádáno; a komuť mnoho poručili, víceť požádají od něho.',
        49: 'Oheň přišel jsem pustiti na zemi, a co chci, jestliže již hoří?',
        50: 'Ale křtem mám křtěn býti, a kterak jsem ssoužen, dokudž se nevykoná!',
        51: 'Což se domníváte, že bych přišel pokoj uvésti na zemi? Nikoli, pravím vám, ale rozdělení.',
        52: 'Nebo již od této chvíle bude jich pět v jednom domě rozděleno, tři proti dvěma, a dva proti třem.',
        53: 'Bude rozdělen otec proti synu, a syn proti otci, mátě proti dceři, a dcera proti mateři, svegruše proti nevěstě své, a nevěsta proti svegruši své.',
        54: 'Pravil také i zástupům: Když vídáte oblak, an vzchází od západu, hned pravíte: Příval jde, a tak bývá.',
        55: 'A když od poledne vítr věje, říkáte: Bude horko, a býváť.',
        56: 'Pokrytci, způsob země i nebe umíte souditi, a kterakž pak tohoto času nesoudíte?',
        57: 'Ano proč i sami od sebe nesoudíte, což spravedlivého?',
        58: 'Když pak jdeš s protivníkem svým k vrchnosti, na cestě přičiň se o to, abys byl zproštěn od něho, aby snad netáhl tebe k soudci, a soudce dal by tebe biřici, a biřic vsadil by tě do žaláře.',
        59: 'Pravím tobě: Nevyjdeš odtud, dokudž bys i toho posledního haléře nenavrátil.',
    },
    13: {
        1: 'Byli pak tu přítomní času toho někteří, vypravujíce jemu o Galilejských, kterýchž krev Pilát smísil s obětmi jejich.',
        2: 'I odpověděv Ježíš, řekl jim: Co mníte, že ti Galilejští byli větší hříšníci nežli všickni Galilejští, že takové věci trpěli?',
        3: 'Nikoli, pravím vám. Nýbrž nebudete-li pokání činiti, všickni též zahynete.',
        4: 'Aneb oněch osmnácte, na kteréž upadla věže v Siloe, a zbila je, zdali se domníváte, že by oni vinni byli nad všecky lidi, přebývající v Jeruzalémě?',
        5: 'Nikoli, pravím vám. Nýbrž nebudete-li pokání činiti, všickni též zahynete.',
        6: 'Pověděl pak toto podobenství: Člověk jeden měl strom fíkový štípený na vinici své. I přišel, hledaje ovoce na něm, ale nenalezl.',
        7: 'I řekl vinaři: Aj, po tři léta přicházím, hledaje ovoce na tom fíku, ale nenalézám. Vytniž jej. Proč i tu zemi darmo kazí?',
        8: 'On pak odpověděv, řekl jemu: Pane, ponechejž ho i tohoto léta, ažť jej okopám a ohnojím,',
        9: 'Zdali by nesl ovoce. Pakliť neponese, potom vytneš jej.',
        10: 'Učil pak v jedné škole v sobotu.',
        11: 'A aj, byla tu žena, kteráž měla ducha nemoci osmnáct let, a byla sklíčena, a nijakž se nemohla zpřímiti.',
        12: 'A uzřev ji Ježíš, zavolal jí k sobě, a řekl jí: Ženo, zproštěna jsi od nemoci své.',
        13: 'I vložil na ni ruce, a i hned zdvihla se, a velebila Boha.',
        14: 'Tedy kníže školní odpověděv, hněvaje se proto, že v den sobotní uzdravoval Ježíš, řekl zástupu: Šest dní jest, v nichž náleží dělati; protož v těch přicházejíce, buďte uzdravováni, a ne v den sobotní.',
        15: 'I odpověděv jemu Pán, řekl: Pokrytče, zdali jeden každý z vás v sobotu neodvazuje vola svého neb osla od jeslí, a nevodí napájeti?',
        16: 'Tato pak dcera Abrahamova, kterouž byl svázal satan, aj, již osmnácte let, což neměla býti rozvázána z svazku tohoto v den sobotní?',
        17: 'A když on to pověděl, zastyděli se všickni protivníci jeho, ale všecken lid radoval se ze všech těch slavných skutků, kteříž se dáli od něho.',
        18: 'I řekl: Čemu podobno jest království Boží, a k čemu je přirovnám?',
        19: 'Podobno jest zrnu horčičnému, kteréž vzav člověk, uvrhl do zahrady své. I rostlo, a učiněno jest v strom veliký, a ptactvo nebeské hnízda sobě dělali na ratolestech jeho.',
        20: 'A opět řekl: K čemu připodobním království Boží?',
        21: 'Podobno jest kvasu, kterýž vzavši žena, zadělala ve třech měřicích mouky, až zkysalo všecko.',
        22: 'I chodil po městech a městečkách, uče, bera se do Jeruzaléma.',
        23: 'I řekl jemu jeden: Pane, co nemnozí jsou ti, kteří spaseni býti mají? On pak řekl jim:',
        24: 'Snažujte se vcházeti těsnou branou; neboť (pravím vám,) mnozí usilovati budou vjíti, ale nebudou moci.',
        25: 'Když vstane hospodář, a zavře dvéře, a počnete vně státi a tlouci na dvéře, řkouce: Pane, Pane, otevři nám, a on odpovídaje, díť vám: Neznám vás, odkud jste:',
        26: 'Tedy počnete říci: Jídali jsme a píjeli před tebou, a na ulicech našich jsi učíval.',
        27: 'I dí: Pravím vám, neznám vás, odkud jste. Odejdětež ode mne všickni činitelé nepravosti.',
        28: 'Tamť bude pláč a škřipení zubů, když uzříte Abrahama, a Izáka, a Jákoba, a všecky proroky v království Božím, sami pak sebe vyhnané ven.',
        29: 'I přijdouť od východu, a od západu, a od půlnoci, i od poledne, a budou stoliti v království Božím.',
        30: 'A aj, jsouť poslední, kteříž budou první, a jsou první, kteříž budou poslední.',
        31: 'A v ten den přistoupili někteří z farizeů, řkouce jemu: Vyjdi, a odejdi odsud, nebo Heródes chce tě zamordovati.',
        32: 'I řekl jim: Jdouce, povězte lišce té: Aj, vymítám ďábly, a uzdravuji dnes a zítra, a třetího dne dokonám.',
        33: 'Ale však musím dnes a zítra i po zejtří choditi; neboť nelze proroku zahynouti kromě Jeruzaléma.',
        34: 'Jeruzaléme, Jeruzaléme, ješto morduješ proroky, a kamenuješ ty, kteříž k tobě bývají posláni, kolikrát jsem chtěl shromážditi dítky tvé, jako slepice kuřátka svá pod křídla? Ale nechtěli jste.',
        35: 'Aj, zanechán bude vám dům váš pustý. Ale jistě pravím vám, že nikoli mne neuzříte, ažť přijde, když díte: Požehnaný, kterýž se béře ve jménu Páně.',
    },
    14: {
        1: 'I stalo se, když všel Ježíš do domu nějakého knížete farizejského v sobotu, aby jedl chléb, že oni šetřili ho.',
        2: 'A aj, člověk nějaký vodnotelný byl před ním.',
        3: 'I odpověděv Ježíš, dí zákonníkům a farizeům, řka: Sluší-li v sobotu uzdravovati?',
        4: 'Oni pak mlčeli. Tedy on dosáh jeho, uzdravil a propustil.',
        5: 'A odpověděv jim, řekl: Čí z vás osel aneb vůl upadl by do studnice, a ne i hned by ho vytáhl v den sobotní?',
        6: 'I nemohli jemu na to odpovědíti.',
        7: 'Pověděl také i pozvaným podobenství, (spatřiv to, kterak přední místa vyvolovali,) řka jim:',
        8: 'Kdybys byl od někoho pozván na svadbu, nesedej na předním místě, aťby snad vzácnější než ty nebyl pozván od něho.',
        9: 'A přijda ten, kterýž tebe i onoho pozval, řekl by tobě: Dej tomuto místo. A tehdy počal bys s hanbou na posledním místě seděti.',
        10: 'Ale když bys byl pozván, jda, posaď se na posledním místě. A kdyby přišel ten, kterýž tebe pozval, řekl by tobě: Příteli, posedni výše, tedy budeš míti chválu před spolustolícími.',
        11: 'Nebo každý, kdož se povyšuje, bude ponížen; a kdož se ponižuje, bude povýšen.',
        12: 'Pravil také i tomu, kterýž ho byl pozval: Když činíš oběd neb večeři, nezov přátel svých, ani bratří svých, ani příbuzných svých, ani sousedů bohatých, aťby snad i oni zase nezvali tebe, a měl bys odplatu.',
        13: 'Ale když činíš hody, povolej chudých, chromých, kulhavých, slepých,',
        14: 'A blahoslavený budeš. Neboť nemají, odkud by odplatili tobě, ale budeť odplaceno při vzkříšení spravedlivých.',
        15: 'I uslyšav to jeden z spolupřísedících, řekl jemu: Blahoslavený, kdož jí chléb v království Božím.',
        16: 'On pak řekl jemu: Člověk nějaký učinil večeři velikou, a pozval mnohých.',
        17: 'I poslal služebníka svého v hodinu večeře, aby řekl pozvaným: Poďte, nebo již připraveno jest všecko.',
        18: 'I počali se všickni jednomyslně vymlouvati. První řekl jemu: Ves jsem koupil, i musím vyjíti a shlédnouti ji; prosím tebe, vymluv mne.',
        19: 'A druhý řekl: Patero spřežení volů koupil jsem, a jdu, abych jich zkusil; prosím tebe, vymluv mne.',
        20: 'A jiný dí: Ženu jsem pojal, a protož nemohu přijíti.',
        21: 'I navrátiv se ten služebník, zvěstoval ty věci pánu svému. Tedy rozhněvav se hospodář, řekl služebníku svému: Vyjdi rychle na rynky a na ulice města, a chudé, i chromé, i kulhavé, a slepé uveď sem.',
        22: 'I řekl služebník: Pane, stalo se, jakž jsi rozkázal, a ještěť místo jest.',
        23: 'Tedy řekl pán služebníku: Vyjdiž na cesty a mezi ploty, a přinuť vjíti, ať se naplní dům můj.',
        24: 'Nebo pravímť vám, že žádný z mužů těch, kteříž pozváni byli, neokusí večeře mé.',
        25: 'Šli pak mnozí zástupové s ním. A obrátiv se, řekl jim:',
        26: 'Jde-li kdo ke mně, a nemá-li v nenávisti otce svého, i mateře, i ženy, i dětí, i bratří, i sestr, ano i té duše své, nemůž býti mým učedlníkem.',
        27: 'A kdožkoli nenese kříže svého, a jde za mnou, nemůž býti mým učedlníkem.',
        28: 'Nebo kdo z vás jest, chtěje stavěti věži, aby prvé sedna, nepočetl nákladu, má-li to, nač by ji dokonal?',
        29: 'Aby snad, když by základ položil, a dokonati nemohl, všickni, kteříž by to viděli, nepočali se posmívati jemu,',
        30: 'Řkouce: Tento člověk počal stavěti, a nemohl dokonati.',
        31: 'Aneb který král, bera se k boji proti jinému králi, zdaliž prvé nesedne, aby se poradil, mohl-li by s desíti tisíci potkati se s tím, kterýž s dvadcíti tisíci táhne proti němu?',
        32: 'Sic jinak, když by onen ještě podál od něho byl, pošle posly k němu, žádaje za to, což jest ku pokoji.',
        33: 'Tak zajisté každý z vás, kdož se neodřekne všech věcí, kterýmiž vládne, nemůž býti mým učedlníkem.',
        34: 'Dobráť jest sůl. Pakli sůl bude zmařena, čím bude napravena?',
        35: 'Ani do země, ani do hnoje se nehodí; ven ji vymítají. Kdo má uši k slyšení, slyš.',
    },
    15: {
        1: 'Přibližovali se pak k němu všickni publikáni a hříšníci, aby ho slyšeli.',
        2: 'I reptali farizeové a zákonníci, řkouce: Tento hříšníky přijímá, a jí s nimi.',
        3: 'I pověděl jim podobenství toto, řka:',
        4: 'Kdyby někdo z vás měl sto ovec, a ztratil by jednu z nich, zdaliž by nenechal devadesáti devíti na poušti, a nešel k té, kteráž zahynula, až by i nalezl ji?',
        5: 'A nalezna, vložil by na ramena svá s radostí.',
        6: 'A přijda domů, svolal by přátely a sousedy, řka jim: Spolu radujte se se mnou, nebo jsem nalezl ovci svou, kteráž byla zahynula.',
        7: 'Pravímť vám, že tak jest radost v nebi nad jedním hříšníkem pokání činícím větší, než nad devadesáti devíti spravedlivými, kteříž nepotřebují pokání.',
        8: 'Aneb žena některá mající grošů deset, ztratila-li by jeden groš, zdaliž nezažže svíce, a nemete domu, a nehledá pilně, dokudž nenalezne?',
        9: 'A když nalezne, svolá přítelkyně a sousedy, řkuci: Spolu radujte se se mnou, nebo jsem nalezla groš, kterýž jsem byla ztratila.',
        10: 'Takť, pravím vám, že jest radost před anděly Božími nad jedním hříšníkem pokání činícím.',
        11: 'Řekl také: Člověk jeden měl dva syny.',
        12: 'Z nichž mladší řekl otci: Otče, dej mi díl statku, kterýž mně náleží. I rozdělil jim statek.',
        13: 'A po nemnohých dnech, shromáždiv všecko mladší ten syn, odšel do daleké krajiny, a tam rozmrhal statek svůj, byv prostopašně živ.',
        14: 'A když všecko utratil, stal se hlad veliký v krajině té, a on počal nouzi trpěti.',
        15: 'I všed, přídržel se jednoho měštěnína krajiny té; a on jej poslal na pole své, aby pásl vepře.',
        16: 'I žádal nasytiti břicho své mlátem, kteréž svině jedly, ale žádný nedával jemu.',
        17: 'Přišed pak sám k sobě, řekl: Jak mnozí nájemníci u otce mého hojnost mají chleba, a já hladem mru!',
        18: 'Vstana, půjdu k otci svému, a dím jemu: Otče, zhřešil jsem proti nebi a před tebou,',
        19: 'Aniž jsem hoden více slouti synem tvým. Učiň mne jako jednoho z nájemníků svých.',
        20: 'I vstav, šel k otci svému. A když ještě opodál byl, uzřel jej otec jeho, a milosrdenstvím byv hnut, přiběh, padl na šíji jeho, a políbil ho.',
        21: 'I řekl jemu syn: Otče, zhřešil jsem proti nebi a před tebou, aniž jsem hoden více slouti synem tvým.',
        22: 'I řekl otec služebníkům svým: Přineste to roucho první, a oblecte jej, a dejte prsten na ruku jeho a obuv na nohy.',
        23: 'A přivedouce to tele tučné, zabíte, a hodujíce, buďme veseli.',
        24: 'Nebo tento syn můj byl umřel, a zase ožil; byl zahynul, a nalezen jest. I počali veseli býti.',
        25: 'Byl pak syn jeho starší na poli. A jda, když se přibližoval k domu, uslyšel zpívání a hluk veselících se.',
        26: 'I povolav jednoho z služebníků, otázal se, co by to bylo.',
        27: 'A on řekl jemu: Bratr tvůj přišel, i zabil otec tvůj tučné tele, že ho zdravého přijal.',
        28: 'I rozhněval se, a nechtěl vjíti. Otec pak jeho vyšed, prosil ho.',
        29: 'A on odpověděv, řekl otci: Aj, tolik let sloužím tobě, a nikdy jsem přikázaní tvého nepřestoupil, a však nikdy jsi mi nedal kozelce, abych s přátely svými vesel pobyl.',
        30: 'Ale když syn tvůj tento, kterýž prožral statek tvůj s nevěstkami, přišel, zabils jemu to tele tučné.',
        31: 'A on řekl jemu: Synu, ty vždycky se mnou jsi, a všecky věci mé jsou tvé.',
        32: 'Ale veseliti a radovati se náleželo. Nebo bratr tvůj tento byl umřel, a zase ožil; zahynul byl, a nalezen jest.',
    },
    16: {
        1: 'Pravil pak i učedlníkům svým: Člověk jeden byl bohatý, kterýž měl šafáře; a ten obžalován jest před ním, jako by mrhal statek jeho.',
        2: 'I povolav ho, řekl jemu: Což to slyším o tobě? Vydej počet z vládařství svého, nebo již nebudeš moci déle vládnouti.',
        3: 'I dí vládař sám v sobě: Co učiním? Teď pán můj odjímá ode mne vládařství. Kopati nemohu, žebrati se stydím.',
        4: 'Vím, co učiním, aby, když budu zsazen z vládařství, přijali mne do svých domů.',
        5: 'I zavolav jednoho každého dlužníka pána svého, řekl prvnímu: Jaks mnoho dlužen pánu mému?',
        6: 'A on řekl: Sto tun oleje. I řekl mu: Vezmi rejistra svá, a sedna rychle, napiš padesát.',
        7: 'Potom druhému řekl: Ty pak jaks mnoho dlužen? Kterýž řekl: Sto korců pšenice. I dí mu: Vezmi rejistra svá, a napiš osmdesát.',
        8: 'I pochválil ten pán vládaře toho nepravého, že opatrně učinil. Nebo synové tohoto světa opatrnější jsou, než synové světla v svých věcech.',
        9: 'I jáť pravím vám: Čiňte sobě přátely z mamony nepravosti, aby, když byste zhynuli, přijali vás do oněch věčných stanů.',
        10: 'Kdo jest věrný v mále, i ve mnoze věrný jest. A kdož v mále jest nepravý, i ve mnozeť nepravý jest.',
        11: 'Poněvadž tedy v mamoně nepravé věrni jste nebyli, spravedlivé kdo vám svěří?',
        12: 'A když jste v cizím věrni nebyli, což vašeho jest, kdo vám dá?',
        13: 'Žádný čeledín nemůž dvěma pánům sloužiti. Nebť zajisté jednoho nenáviděti bude, a druhého milovati, aneb jednoho přídržeti se bude, a druhým pohrdne. Nemůžte Bohu sloužiti a mamoně.',
        14: 'Slyšeli pak toto všecko i farizeové, kteříž byli lakomí, a posmívali se jemu.',
        15: 'I dí jim: Vy jste, ješto se sami spravedliví činíte před lidmi, ale Bůhť zná srdce vaše; nebo což jest u lidí vysokého, ohavnost jest před Bohem.',
        16: 'Zákon a proroci až do Jana, a od té chvíle království Boží zvěstuje se, a každý se do něho násilně tiskne.',
        17: 'Snázeť jest zajisté nebi i zemi pominouti, nežli v zákoně jednomu tytlíku zahynouti.',
        18: 'Každý, kdož propustí manželku svou, a jinou pojímá, cizoloží; a kdož propuštěnou od muže pojímá, cizoloží.',
        19: 'Byl pak člověk jeden bohatý, a obláčel se v šarlat a v kment, a hodoval na každý den stkvostně.',
        20: 'A byl jeden žebrák, jménem Lazar, kterýž ležel u vrat jeho vředovitý,',
        21: 'Žádaje nasycen býti těmi drobty, kteříž padali z stolu bohatce. Ale i psi přicházejíce, lízali vředy jeho.',
        22: 'I stalo se, že ten žebrák umřel, a nesen jest od andělů do lůna Abrahamova. Umřel pak i bohatec, a pohřben jest.',
        23: 'Potom v pekle pozdvih očí svých, v mukách jsa, uzřel Abrahama zdaleka, a Lazara v lůnu jeho.',
        24: 'I zvolav bohatec, řekl: Otče Abrahame, smiluj se nade mnou, a pošli Lazara, ať omočí konec prstu svého v vodě, a svlaží jazyk můj; nebo se mučím v tomto plameni.',
        25: 'I řekl Abraham: Synu, rozpomeň se, žes ty vzal dobré věci své v životě svém, a Lazar též zlé. Nyní pak tento se těší, ale ty se mučíš.',
        26: 'A nad to nade všecko mezi námi a vámi propast veliká utvrzena jest, aby ti, kteříž chtí odsud k vám jíti, nemohli, ani od onud k nám přejíti.',
        27: 'I řekl: Ale prosím tebe, otče, abys ho poslal do domu otce mého.',
        28: 'Neboť mám pět bratrů. Ať jim svědčí, aby i oni nepřišli do tohoto místa muk.',
        29: 'I řekl jemu Abraham: Majíť Mojžíše a proroky, nechť jich poslouchají.',
        30: 'A on řekl: Nic, otče Abrahame, ale kdyby kdo z mrtvých šel s nim, budou pokání činiti.',
        31: 'I řekl mu: Poněvadž Mojžíše a proroků neposlouchají, aniž byť kdo z mrtvých vstal, uvěří jemu.',
    },
    17: {
        1: 'Tedy řekl učedlníkům: Není možné, aby nepřišla pohoršení, ale běda, skrze kohož přicházejí.',
        2: 'Lépe by mu bylo, aby žernov osličí vložen byl na hrdlo jeho, a uvržen byl do moře, než by pohoršil jednoho z těchto maličkých.',
        3: 'Šetřte se. Zhřešil-li by pak proti tobě bratr tvůj, potresci ho, a bude-liť toho želeti, odpusť mu.',
        4: 'A byť pak sedmkrát za den zhřešil proti tobě, a sedmkrát za den obrátil se k tobě, řka: Žel mi toho, odpusť mu.',
        5: 'I řekli apoštolé Pánu: Přispoř nám víry.',
        6: 'I dí Pán: Kdybyste měli víru jako zrno horčičné, řekli byste této moruši: Vykořeň se, a přesaď se do moře, a uposlechla by vás.',
        7: 'Kdo pak jest z vás, maje služebníka, ješto oře aneb pase, aby jemu, když by se s pole navrátil, hned řekl: Poď a sedni za stůl?',
        8: 'Anobrž zdali nedí jemu: Připrav, ať povečeřím, a opáše se, služ mi, až se najím a napím, a potom i ty jez a pí?',
        9: 'Zdali děkuje služebníku tomu, že učinil to, což mu bylo rozkázáno? Nezdá mi se.',
        10: 'Tak i vy, když učiníte všecko, což vám přikázáno, rcete: Služebníci neužiteční jsme. Což jsme povinni byli učiniti, učinili jsme.',
        11: 'I stalo se, když se bral do Jeruzaléma, že šel skrze Samaří a Galilei.',
        12: 'A když vcházel do nějakého městečka, potkalo se s ním deset mužů malomocných, kteříž stáli zdaleka.',
        13: 'A pozdvihše hlasu, řekli: Ježíši přikazateli, smiluj se nad námi.',
        14: 'Kteréžto on uzřev, řekl jim: Jdouce, ukažte se kněžím. I stalo se, když šli, že očištěni jsou.',
        15: 'Jeden pak z nich uzřev, že jest uzdraven, navrátil se, s velikým hlasem velebě Boha.',
        16: 'A padl na tvář k nohám jeho, díky čině jemu. A ten byl Samaritán.',
        17: 'I odpověděv Ježíš, řekl: Zdaliž jich deset není očištěno? A kdež jich devět?',
        18: 'Nenalezli se, aby vrátíce se, chválu Bohu vzdali, jediné cizozemec tento?',
        19: 'I řekl jemu: Vstana jdi, víra tvá tě uzdravila.',
        20: 'Byv pak otázán od farizeů, kdy přijde království Boží, odpověděl jim, a řekl: Nepřijdeť království Boží s šetřením.',
        21: 'Aniž řeknou: Aj, tuto, aneb aj, tamto. Nebo aj, království Boží jestiť mezi vámi.',
        22: 'I řekl učedlníkům: Přijdou dnové, že budete žádati viděti v jeden den Syna člověka, ale neuzříte.',
        23: 'A dějíť vám: Aj, zde, aneb hle, tamto. Ale nechoďte, aniž následujte.',
        24: 'Nebo jakož blesk osvěcující se z jedné krajiny, kteráž pod nebem jest, až do druhé, kteráž též pod nebem jest, svítí, tak bude i Syn člověka ve dni svém.',
        25: 'Ale nejprvé musí mnoho trpěti, a zavržen býti od národu tohoto.',
        26: 'A jakož se dálo za dnů Noé, tak bude i za dnů Syna člověka.',
        27: 'Jedli, pili, ženili se, vdávaly se až do toho dne, v kterémž Noé všel do korábu; i přišla potopa, a zahladila všecky.',
        28: 'A též podobně, jakž se dálo ve dnech Lotových: Jedli, pili, kupovali, prodávali, štěpovali, stavěli.',
        29: 'Ale dne toho, když vyšel Lot z Sodomy, dštil ohněm a sirou s nebe, a zahladil všecky.',
        30: 'Takť nápodobně bude v ten den, když se Syn člověka zjeví.',
        31: 'V ten den kdo by byl na střeše, a nádobí jeho v domu, nesstupuj, aby je pobral; a kdo na poli, též nevracuj se zase.',
        32: 'Pomněte na Lotovu ženu.',
        33: 'Kdož by koli hledal duši svou zachovati, ztratíť ji; a kdož by ji koli ztratil, obživíť ji.',
        34: 'Pravímť vám: V tu noc budou dva na loži jednom; jeden bude vzat, a druhý opuštěn.',
        35: 'Dvě budou mleti spolu; jedna bude vzata, a druhá opuštěna.',
        36: 'Dva budou na poli; jeden bude vzat, a druhý opuštěn.',
        37: 'I odpověděvše, řekli jemu: Kde, Pane? On pak řekl jim: Kdežť bude tělo, tamť se shromáždí i orlice.',
    },
    18: {
        1: 'Pověděl jim také i podobenství, kterak by potřebí bylo vždycky se modliti a neoblevovati,',
        2: 'Řka: Byl jeden soudce v městě jednom, kterýž se Boha nebál, a člověka nestyděl.',
        3: 'Byla pak vdova v témž městě. I přišla k němu, řkuci: Pomsti mne nad protivníkem mým.',
        4: 'On pak dlouho nechtěl. Ale potom řekl sám v sobě: Ač se Boha nebojím, ani člověka nestydím,',
        5: 'Však že mi pokoje nedá tato vdova, pomstím jí, aby naposledy přijduci, neuhaněla mne.',
        6: 'I dí Pán: Slyšte, co praví ten soudce nepravý.',
        7: 'A což by pak Bůh nepomstil vyvolených svých, volajících k němu dnem i nocí, ačkoli i prodlévá jim?',
        8: 'Pravímť vám, žeť jich brzo pomstí. Ale když přijde Syn člověka, zdaliž nalezne víru na zemi?',
        9: 'I řekl také proti některým, kteříž v sebe doufali, že by spravedliví byli, jiných za nic nevážíce, podobenství toto:',
        10: 'Dva muži vstupovali do chrámu, aby se modlili, jeden farizeus, a druhý publikán.',
        11: 'Farizeus stoje, takto se sám v sobě modlil: Bože, děkuji tobě, že nejsem jako jiní lidé, dráči, nespravedliví, cizoložníci, aneb jako i tento publikán.',
        12: 'Postím se dvakrát do téhodne, desátky dávám ze všech věcí, kterýmiž vládnu.',
        13: 'Publikán pak zdaleka stoje, nechtěl ani očí k nebi pozdvihnouti. Ale bil se v prsy své, řka: Bože, buď milostiv mně hříšnému.',
        14: 'Pravímť vám: Odšel tento, ospravedlněn jsa, do domu svého, a ne onen. Nebo každý, kdož se povyšuje, bude ponížen; a kdož se ponižuje, bude povýšen.',
        15: 'Přinášeli také k němu i nemluvňátka, aby se jich dotýkal. To viděvše učedlníci, přimlouvali jim.',
        16: 'Ale Ježíš svolav je, řekl: Nechte dítek, ať jdou ke mně, a nebraňte jim, nebo takovýchť jest království Boží.',
        17: 'Amen pravím vám: Kdož by koli nepřijal království Božího jako dítě, nevejdeť nikoli do něho.',
        18: 'I otázalo se ho jedno kníže, řka: Mistře dobrý, co čině, život věčný obdržím?',
        19: 'I řekl jemu Ježíš: Co mne nazýváš dobrým? Žádný není dobrý, než jediný, totiž Bůh.',
        20: 'Umíš přikázaní: Nezcizoložíš, nezabiješ, nepokradeš, nepromluvíš křivého svědectví, cti otce svého i matku svou.',
        21: 'On pak řekl: Toho všeho ostříhal jsem od své mladosti.',
        22: 'Ale slyšav to Ježíš, řekl mu: Ještěť se jednoho nedostává. Všecko, což máš, prodej, a rozdej chudým, a budeš míti poklad v nebi, a poď, následuj mne.',
        23: 'On pak uslyšav to, zarmoutil se; byl zajisté bohatý velmi.',
        24: 'A viděv jej Ježíš zarmouceného, řekl: Aj, jak nesnadně ti, kdož statky mají, do království Božího vejdou!',
        25: 'Snáze jest zajisté velbloudu skrze jehelnou dírku projíti, nežli bohatému vjíti do království Božího.',
        26: 'Tedy řekli ti, kteříž to slyšeli: I kdož může spasen býti?',
        27: 'A on dí: Což jest nemožného u lidí, možné jest u Boha.',
        28: 'I řekl Petr: Aj, my opustili jsme všecko, a šli jsme za tebou.',
        29: 'On pak řekl jim: Amen pravím vám, že není žádného, kterýž by opustil dům, neb rodiče, neb bratří, neb manželku, neb dítky, pro království Boží,',
        30: 'Aby nevzal v tomto času mnohem více, v budoucím pak věku života věčného.',
        31: 'Tedy pojav dvanácte, řekl jim: Aj, vstupujeme do Jeruzaléma, a naplníť se všecko Synu člověka to, což psáno jest skrze proroky.',
        32: 'Nebo vydán bude pohanům, a bude posmíván, a zlehčen, i uplván.',
        33: 'A ubičujíce, zamordují jej, ale třetího dne z mrtvých vstane.',
        34: 'Oni pak tomu nic nerozuměli, a bylo slovo to skryto před nimi, aniž věděli, co se pravilo.',
        35: 'I stalo se, když se přibližovali k Jericho, slepý jeden seděl podlé cesty, žebře.',
        36: 'A slyšev zástup pomíjející, otázal se, co by to bylo.',
        37: 'I oznámili jemu, že Ježíš Nazaretský tudy jde.',
        38: 'I zvolal, řka: Ježíši, synu Davidův, smiluj se nade mnou.',
        39: 'A ti, kteříž napřed šli, přimlouvali mu, aby mlčal. Ale on mnohem více volal: Synu Davidův, smiluj se nade mnou.',
        40: 'Tedy zastaviv se Ježíš, rozkázal ho k sobě přivésti. A když se přibližoval, otázal se ho,',
        41: 'Řka: Co chceš, ať učiním? On pak dí: Pane, ať vidím.',
        42: 'A Ježíš řekl jemu: Prohlédni. Víra tvá tě uzdravila.',
        43: 'A i hned prohlédl, a šel za ním, velebě Boha. A všecken lid viděv to, vzdal chválu Bohu.',
    },
    19: {
        1: 'A všed, bral se přes Jericho.',
        2: 'A aj, muž, jménem Zacheus, a ten byl hejtman nad celnými, a byl bohatý.',
        3: 'I žádostiv byl viděti Ježíše, kdo by byl; a nemohl pro zástup, nebo postavy malé byl.',
        4: 'A předběh napřed, vstoupil na strom planého fíku, aby jej viděl; nebo tudy měl jíti.',
        5: 'A když přišel k tomu místu, pohleděv zhůru Ježíš, uzřel jej, i řekl jemu: Zachee, spěšně sstup dolů, nebo dnes v domu tvém musím zůstati.',
        6: 'I sstoupil rychle, a přijal jej radostně.',
        7: 'A viděvše to všickni, reptali, řkouce: K člověku hříšnému se obrátil.',
        8: 'Stoje pak Zacheus, řekl Pánu: Aj, polovici statku svého, Pane, dávám chudým, a oklamal-li jsem v čem koho, navracuji to čtvernásob.',
        9: 'I dí jemu Ježíš: Dnes spasení stalo se domu tomuto, proto že i on jest syn Abrahamův.',
        10: 'Nebo přišel Syn člověka, aby hledal a spasil, což bylo zahynulo.',
        11: 'Toho když oni poslouchali, promluvil k nim dále podobenství, proto že byl blízko od Jeruzaléma, a že se oni domnívali, že by se hned mělo zjeviti království Boží.',
        12: 'I řekl: Člověk jeden rodu znamenitého odšel do daleké krajiny, aby přijal království, a zase se navrátil.',
        13: 'I povolav desíti služebníků svých, dal jim deset hřiven, a řekl jim: Kupčtež, dokudž nepřijdu.',
        14: 'Měšťané pak jeho nenáviděli ho, a poslali poselství za ním, řkouce: Nechcemeť, aby tento kraloval nad námi.',
        15: 'I stalo se, když se navrátil, přijav království, že rozkázal zavolati těch svých služebníků, kterýmž byl dal peníze, aby zvěděl, jak kdo mnoho získal.',
        16: 'I přišel první, řka: Pane, hřivna tvá deset hřiven získala.',
        17: 'I řekl jemu: To dobře, služebníče dobrý. Že jsi nad málem byl věrný, mějž moc nad desíti městy.',
        18: 'A druhý přišel, řka: Pane, hřivna tvá získala pět hřiven.',
        19: 'I tomu řekl: I ty budiž nad pěti městy.',
        20: 'A jiný přišel, řka: Pane, aj, teď hřivna tvá, kterouž jsem měl složenou v šátku.',
        21: 'Nebo jsem se bál tebe, ješto jsi člověk přísný; béřeš, čeho jsi nepoložil, a žneš, čeho jsi nerozsíval.',
        22: 'I řekl jemu: Z úst tvých soudím tebe, služebníče zlý. Věděl jsi, že jsem já člověk přísný, bera, což jsem nepoložil, a žna, čehož jsem nerozsíval.',
        23: 'I proč jsi tedy nedal peněz mých na stůl, a já přijda, byl bych je vzal i s užitky.',
        24: 'I řekl těm, kteříž tu stáli: Vezměte od něho tu hřivnu, a dejte tomu, kterýž má deset hřiven.',
        25: 'I řekli jemu: Pane, máť deset hřiven.',
        26: 'Jistě pravím vám: Že každému, kdož má, bude dáno, ale od toho, kterýž nemá, i to, což má, bude odjato.',
        27: 'Ty pak nepřátely mé, kteříž nechtěli, abych nad nimi kraloval, přiveďte sem, a zmordujte přede mnou.',
        28: 'To pověděv, šel napřed, vstupuje k Jeruzalému.',
        29: 'I stalo se, když se přiblížil k Betfagi a k Betany, k hoře, kteráž slove Olivetská, poslal dva učedlníky své,',
        30: 'Řka: Jděte do městečka, kteréž proti vám jest. Do kteréhož vejdouce, naleznete oslátko přivázané, na němž nikdy žádný z lidí neseděl. Odvěžtež je, a přiveďte ke mně.',
        31: 'A optal-liť by se vás kdo, proč odvazujete, tak díte jemu: Proto že Pán ho potřebuje.',
        32: 'Tedy odšedše ti, kteříž byli posláni, nalezli, jakž jim byl pověděl.',
        33: 'A když odvazovali to oslátko, řekli páni jeho k nim: Proč odvazujete oslátko?',
        34: 'A oni řekli: Pán ho potřebuje.',
        35: 'I přivedli je k Ježíšovi, a vloživše roucha svá na to oslátko, vsadili na ně Ježíše.',
        36: 'A když on jel, stlali roucha svá na cestě.',
        37: 'Když se pak již přibližoval k místu tomu, kudyž scházejí s hory Olivetské, počalo všecko množství učedlníků radostně chváliti Boha hlasem velikým ze všech divů, kteréž byli viděli,',
        38: 'Řkouce: Požehnaný král, kterýž se béře ve jménu Páně. Pokoj na nebi, a sláva na výsostech.',
        39: 'Ale někteří z farizeů, kteříž tu byli v zástupu, řekli jemu: Mistře, potresci učedlníků svých.',
        40: 'I odpověděv, řekl jim: Pravímť vám: Budou-li tito mlčeti, kamení hned bude volati.',
        41: 'A když se přiblížil, uzřev město, plakal nad ním,',
        42: 'Řka: Ó kdybys poznalo i ty, a to aspoň v takový tento den tvůj, které by věci ku pokoji tobě byly, ale skrytoť jest to nyní před očima tvýma.',
        43: 'Nebo přijdou na tě dnové, obklíčí tě nepřátelé tvoji valem, a oblehnou tebe, a ssouží tě se všech stran.',
        44: 'A s zemí srovnají tě, i syny tvé v tobě, a nenechajíť v tobě kamene na kameni, proto že jsi nepoznalo času navštívení svého.',
        45: 'A všed do chrámu, počal vymítati prodavače a kupce z něho,',
        46: 'Řka jim: Psáno jest: Dům můj dům modlitby jest, vy jste jej pak učinili peleší lotrovskou.',
        47: 'I učil na každý den v chrámě. Přední pak kněží {biskupové} a zákonníci i přední v lidu hledali ho zahladiti.',
        48: 'Ale nenalezli, co by učinili. Nebo všecken lid jej sobě liboval, poslouchaje ho.',
    },
    20: {
        1: 'I stalo se těch dnů v jeden den, když on učil lid v chrámě, a kázal evangelium, že přišli k tomu přední kněží {biskupové} a zákonníci s staršími.',
        2: 'I řekli jemu: pověz nám, jakou mocí tyto věci činíš, aneb kdo jest ten, kterýž tobě tuto moc dal?',
        3: 'I odpověděv, řekl jim: Otížiť se i já vás na jednu věc; protož pověztež mi:',
        4: 'Křest Janův s nebe-li byl, čili z lidí?',
        5: 'Oni pak uvažovali to mezi sebou, řkouce: Jestliže bychom řekli: S nebe, díť: Pročež jste tedy neuvěřili jemu?',
        6: 'Pakli díme: Z lidí, lid všecken ukamenuje nás; nebo cele tak drží, že Jan jest prorok.',
        7: 'I odpověděli: Že nevědí, odkud byl.',
        8: 'I řekl jim Ježíš: Aniž já vám povím, jakou mocí toto činím.',
        9: 'I počal lidu praviti podobenství toto: Člověk jeden štípil vinici, a pronajal ji vinařům, a sám odšel přes pole na dlouhé časy.',
        10: 'A v čas slušný poslal k těm vinařům služebníka, aby užitek z vinice dali jemu. Ti pak vinaři zmrskavše jej, pustili prázdného.',
        11: 'I poslal druhého služebníka. Oni pak i toho zmrskavše a zohavivše, pustili prázdného.',
        12: 'I poslal třetího. Ale oni i toho zranivše, vystrčili ven.',
        13: 'Tedy řekl pán té vinice: Co učiním? Pošli svého milého syna. Snad když toho uzří, ustýdnou se.',
        14: 'Ale vinaři uzřevše jej, rozmlouvali mezi sebou, řkouce: Tentoť jest dědic; poďte, zabíme jej, aby naše bylo to dědictví.',
        15: 'A vystrčivše jej ven z vinice, zamordovali. Což tedy učiní jim pán té vinice?',
        16: 'Přijde a vyhladí vinaře ty, a dá vinici jiným. To uslyšavše, řekli: Odstup to.',
        17: 'Ale on pohleděv na ně, řekl: Co jest pak to, což napsáno jest: Kámen, kterýmž pohrdli stavitelé, ten učiněn jest v hlavu úhelní?',
        18: 'Každý, kdož padne na ten kámen, rozrazí se; a na kohož by on upadl, potřeť jej.',
        19: 'I hledali přední kněží {biskupové} a zákonníci, jak by naň vztáhli ruce v tu hodinu, ale báli se lidu. Nebo porozuměli, že by na ně mluvil podobenství to.',
        20: 'Tedy střehouce ho, poslali špehéře, kteříž by se spravedlivými činili, aby ho polapili v řeči, a potom jej vydali vrchnosti a v moc hejtmanu.',
        21: 'I otázali se ho, řkouce: Mistře, víme, že právě mluvíš a učíš, a nepřijímáš osoby, ale v pravdě cestě Boží učíš.',
        22: 'Sluší-li nám daň dávati císaři, čili nic?',
        23: 'Ale porozuměv chytrosti jejich, dí jim: Co mne pokoušíte?',
        24: 'Ukažte mi peníz. Čí má obraz a nápis? I odpověděvše, řekli: Císařův.',
        25: 'On pak řekl jim: Dejtež tedy, co jest císařova, císaři, a co jest Božího, Bohu.',
        26: 'I nemohli ho za slovo popadnouti před lidem, a divíce se odpovědi jeho, umlkli.',
        27: 'Přistoupivše pak někteří z saduceů, (kteříž odpírají býti vzkříšení,) otázali se ho,',
        28: 'Řkouce: Mistře, Mojžíš napsal nám: Kdyby bratr něčí umřel, maje manželku, a umřel by bez dětí, aby ji pojal bratr jeho za manželku, a vzbudil símě bratru svému.',
        29: 'I bylo sedm bratří, a první pojav ženu, umřel bez dětí.',
        30: 'I pojal druhý tu ženu, a umřel i ten bez dětí.',
        31: 'Potom třetí pojal ji, též i všech těch sedm, a nezůstavivše dětí, zemřeli.',
        32: 'Nejposléze po všech umřela i ta žena.',
        33: 'Protož při vzkříšení, kterého z nich bude ta žena, poněvadž sedm jich mělo ji za manželku?',
        34: 'A odpovídaje, řekl jim Ježíš: Synové tohoto věku žení se a vdávají.',
        35: 'Ale ti, kteříž hodni jmíni budou dosáhnouti onoho věku a vzkříšení z mrtvých, ani se ženiti nebudou ani vdávati.',
        36: 'Nebo ani umírati více nebudou moci, andělům zajisté rovni budou. A jsou synové Boží, poněvadž jsou synové vzkříšení.',
        37: 'A že mrtví vstanou z mrtvých, i Mojžíš ukázal při onom kři, když nazývá Pána Bohem Abrahamovým, a Bohem Izákovým, a Bohem Jákobovým.',
        38: 'Bůhť pak není mrtvých, ale živých, nebo všickni jsou jemu živi.',
        39: 'Tedy odpověděvše někteří z zákonníků, řekli: Mistře, dobře jsi pověděl.',
        40: 'I nesměli se jeho na nic více tázati.',
        41: 'Řekl pak jim: Kterak praví Krista býti synem Davidovým?',
        42: 'A sám David praví v knize žalmů: Řekl Pán Pánu mému: Seď na pravici mé,',
        43: 'Ažť položím nepřátely tvé v podnož noh tvých?',
        44: 'Poněvadž David jej Pánem nazývá, i kterakž syn jeho jest?',
        45: 'I řekl učedlníkům svým přede vším lidem:',
        46: 'Varujte se zákonníků, kteříž rádi chodí v krásném rouše, a milují pozdravování na trzích a přední stolice v školách, a první místo na večeřích.',
        47: 'Kteříž zžírají domy vdovské pod zámyslem dlouhé modlitby. Tiť vezmou těžší odsouzení.',
    },
    21: {
        1: 'A pohleděv, uzřel bohaté, kteříž metali dary své do pokladnice.',
        2: 'Uzřel pak i jednu vdovu chudičkou, ana uvrhla tam dva šarty.',
        3: 'I řekl: V pravdě pravím vám, že vdova tato chudá více než všickni uvrhla.',
        4: 'Nebo všickni tito z toho, což jim zbývalo, dali dary Bohu, tato pak z své chudoby všecku živnost svou, kterouž měla, uvrhla.',
        5: 'A když někteří pravili o chrámu, kterak by kamením pěkným i okrasami ozdoben byl, řekl:',
        6: 'Nač se to díváte? Přijdouť dnové, v nichž nebude zůstaven kámen na kameni, kterýž by nebyl zbořen.',
        7: 'I otázali se ho, řkouce: Mistře, kdy to bude? A které znamení, když se to bude míti státi?',
        8: 'On pak řekl: Vizte, abyste nebyli svedeni. Nebo mnozí přijdou ve jménu mém, řkouce: Já jsem, a čas se blíží. Protož nepostupujte po nich.',
        9: 'Když pak uslyšíte o válkách a různicech, nestrachujte se; neboť musí to prvé býti, ale ne i hned konec.',
        10: 'Tehdy pravil jim: Povstaneť národ proti národu, a království proti království.',
        11: 'A země třesení veliká budou po místech, a hladové, a morové, hrůzy i zázrakové s nebe velicí.',
        12: 'Ale před tím přede vším vztáhnou ruce své na vás, a protiviti se budou, vydávajíce vás do škol a žalářů, vodíce k králům a k vládařům pro jméno mé.',
        13: 'A toť se vám díti bude na svědectví.',
        14: 'Protož složtež to v srdcích svých, abyste se nestarali, kterak byste odpovídati měli.',
        15: 'Jáť zajisté dám vám ústa a moudrost, kteréž nebudou moci odolati, ani proti ní ostáti všickni protivníci vaši.',
        16: 'Budete pak zrazováni i od rodičů a od bratří, od příbuzných i od přátel, a zmordují některé z vás.',
        17: 'A budete v nenávisti u všech pro jméno mé.',
        18: 'Ale ani vlas s hlavy vaší nikoli nezahyne.',
        19: 'V trpělivosti své vládněte dušemi svými.',
        20: 'Když pak uzříte obležený od vojska Jeruzalém, tehdy vězte, žeť se přiblížilo zkažení jeho.',
        21: 'Tehdy ti, kdož jsou v Judstvu, utíkejte k horám, a kdo u prostřed něho, vyjděte, a kteří v končinách, nevcházejte do něho.',
        22: 'Neboť budou dnové pomsty, aby se naplnilo všecko, což psáno jest.',
        23: 'Ale běda těhotným a těm, kteréž kojí v těch dnech. Neboť bude dav veliký v této zemi, a hněv nad lidem tímto.',
        24: 'I padati budou ostrostí meče, a zjímaní vedeni budou mezi všecky národy, a Jeruzalém tlačen bude od pohanů, dokudž se nenaplní časové pohanů.',
        25: 'I budouť znamení na slunci a na měsíci i na hvězdách, a na zemi ssoužení národů, nevědoucích se kam díti, když zvuk vydá moře a vlnobití,',
        26: 'Tak že zmrtvějí lidé pro strach a pro očekávání těch věcí, kteréž přijdou na všecken svět. Nebo moci nebeské pohybovati se budou.',
        27: 'A tehdyť uzří Syna člověka, an se béře v oblace s mocí a slavou velikou.',
        28: 'A když se toto počne díti, pohleďtež a pozdvihnětež hlav svých, proto že se přibližuje vykoupení vaše.',
        29: 'I pověděl jim podobenství: Patřte na fíkový strom i na všecka stromoví.',
        30: 'Když se již pučí, vidouce to, sami to znáte, že blízko jest již léto.',
        31: 'Takž i vy, když uzříte, ano se tyto věci dějí, vězte, že blízko jest království Boží.',
        32: 'Amen pravím vám, že nepomine věk tento, až se všecko stane.',
        33: 'Nebe a země pominou, ale slova má nepominou.',
        34: 'Pilně se pak varujte, aby snad nebyla obtížená srdce vaše obžerstvím a opilstvím a pečováním o tento život, a v náhle přikvačil by vás ten den.',
        35: 'Nebo jako osídlo přijde na všecky, kteříž přebývají na tváři vší země.',
        36: 'Protož bděte, všelikého času modléce se, abyste hodni byli ujíti všech těch věcí, kteréž se budou díti, a postaviti se před Synem člověka.',
        37: 'I býval ve dne v chrámě, uče, ale v noci vycházeje, přebýval na hoře, kteráž slove Olivetská.',
        38: 'A všecken lid na úsvitě přicházel k němu do chrámu, aby ho poslouchal.',
    },
    22: {
        1: 'Přibližoval se pak svátek přesnic, kterýž slove velikanoc.',
        2: 'I hledali přední kněží {biskupové} a zákonníci, kterak by jej vyhladili; nebo obávali se lidu.',
        3: 'Tedy vstoupil satan do Jidáše, přijmím Iškariotského, kterýž byl z počtu dvanácti.',
        4: 'A on odšed, mluvil s předními kněžími {biskupy}, a s úředníky, kterak by ho jim zradil.',
        5: 'I zradovali se, a smluvili s ním, že mu chtí peníze dáti.',
        6: 'I slíbil, a hledal příhodného času, aby ho jim zradil bez zástupu.',
        7: 'Tedy přišel den přesnic, v kterémž zabit měl býti beránek.',
        8: 'I poslal Petra a Jana, řka: Jdouce, připravte nám beránka, abychom jedli.',
        9: 'A oni řekli mu: Kde chceš, ať připravíme?',
        10: 'On pak řekl jim: Aj, když vcházeti budete do města, potkáť vás člověk, dčbán vody nesa. Jdětež za ním do domu, do kteréhož vejde.',
        11: 'A díte hospodáři toho domu: Vzkazuje tobě Mistr: Kde jest síň, kdež budu jísti beránka s učedlníky svými?',
        12: 'A onť vám ukáže večeřadlo veliké podlážené. Tam připravte.',
        13: 'I odšedše, nalezli, jakž jim pověděl, a připravili beránka.',
        14: 'A když přišel čas, posadil se za stůl, a dvanácte apoštolů s ním.',
        15: 'I řekl jim: Žádostí žádal jsem tohoto beránka jísti s vámi, prvé než bych trpěl.',
        16: 'Nebo pravímť vám, žeť ho již více nebudu jísti, ažť se naplní v království Božím.',
        17: 'A vzav kalich, a díky činiv, řekl: Vezměte jej a dělte mezi sebou.',
        18: 'Nebo pravím vám, žeť nebudu píti z plodu vinného kořene, ažť království Boží přijde.',
        19: 'A vzav chléb, a díky činiv, lámal a dal jim, řka: To jest tělo mé, kteréž se za vás dává. To čiňte na mou památku.',
        20: 'Takž i kalich, když bylo po večeři, řka: Tento kalich jest ta nová smlouva v mé krvi, kteráž se za vás vylévá.',
        21: 'Ale aj, ruka zrádce mého se mnou za stolem.',
        22: 'A Syn zajisté člověka jde, tak jakž jest uloženo, ale běda člověku tomu, kterýž ho zrazuje.',
        23: 'Tedy oni počali vyhledávati mezi sebou, kdo by z nich byl, kterýž by to měl učiniti.',
        24: 'Stal se pak i svár mezi nimi, kdo by z nich zdál se býti největší.',
        25: 'On pak řekl jim: Králové národů panují nad nimi, a kteříž moc mají nad nimi, dobrodincové slovou.',
        26: 'Ale vy ne tak. Nýbrž kdož největší jest mezi vámi, budiž jako nejmenší, a kdož vůdce jest, jako sloužící.',
        27: 'Nebo kdo větší, ten-li, kterýž sedí, čili ten, kterýž slouží? Zdali ne ten, kterýž sedí? Ale já mezi vámi jsem jako ten, kterýž slouží.',
        28: 'Vy pak jste ti, kteříž jste v mých pokušeních se mnou zůstali.',
        29: 'A jáť vám způsobuji, jakož mi způsobil Otec můj, království,',
        30: 'Abyste jedli a pili za stolem mým v království mém, a seděli na stolicích, soudíce dvanáctero pokolení Izraelské.',
        31: 'I řekl Pán: Šimone, Šimone, aj, satan vyprosil, aby vás tříbil jako pšenici.',
        32: 'Ale jáť jsem prosil za tebe, aby nezhynula víra tvá. A ty někdy obrátě se, potvrzuj bratří svých.',
        33: 'A on řekl jemu: Pane, s tebou hotov jsem i do žaláře i na smrt jíti.',
        34: 'On pak dí: Pravím tobě, Petře, nezazpíváť dnes kohout, až prvé třikrát zapříš, že neznáš mne.',
        35: 'I řekl jim: Když jsem vás posílal bez pytlíka, a bez mošny, a bez obuvi, zdali jste v čem nedostatek měli? A oni řekli: V ničemž.',
        36: 'Tedy dí jim: Ale nyní, kdo má pytlík, vezmi a též i mošnu; a kdož meče nemá, prodej sukni svou, a kup sobě.',
        37: 'Nebo pravím vám, že se ještě to písmo naplniti musí na mně: A s nešlechetnými počten jest. Nebo ty věci, kteréž svědčí o mně, konec berou.',
        38: 'Oni pak řekli: Pane, aj, dva meče teď. A on řekl jim: Dostiť jest.',
        39: 'A vyšed, šel podlé obyčeje svého na horu Olivovou, a šli za ním i učedlníci jeho.',
        40: 'A když přišel na místo, řekl jim: Modlte se, abyste nevešli v pokušení.',
        41: 'A sám vzdáliv se od nich, jako by mohl kamenem dohoditi, a poklek na kolena, modlil se,',
        42: 'Řka: Otče, chceš-li, přenes kalich tento ode mne, ale však ne má vůle, ale tvá staň se.',
        43: 'I ukázal se jemu anděl s nebe, posiluje ho.',
        44: 'A jsa v boji, horlivěji se modlil. I učiněn jest pot jeho jako krůpě krve tekoucí na zemi.',
        45: 'A vstav od modlitby, a přišed k učedlníkům, nalezl je, ani spí zámutkem.',
        46: 'I řekl jim: Co spíte? Vstaňte a modlte se, abyste nevešli v pokušení.',
        47: 'A když on ještě mluvil, aj, zástup, a ten, kterýž sloul Jidáš, jeden ze dvanácti, šel napřed, a přiblížil se k Ježíšovi, aby jej políbil.',
        48: 'Ježíš pak řekl jemu: Jidáši, políbením Syna člověka zrazuješ.',
        49: 'A vidouce ti, kteříž při něm byli, k čemu se chýlí, řekli jemu: Pane, budeme-liž bíti mečem?',
        50: 'I udeřil jeden z nich služebníka nejvyššího kněze {biskupova}, a uťal ucho jeho pravé.',
        51: 'A Ježíš odpověděv, řekl: Nechtež až potud. A dotek se ucha jeho, uzdravil jej.',
        52: 'I dí Ježíš těm, kteříž přišli na něho, předním kněžím {biskupům} a úředníkům chrámu a starším: Jako na lotra vyšli jste s meči a s kyjmi.',
        53: 'Ješto na každý den býval jsem s vámi v chrámě, a nevztáhli jste rukou na mne. Ale totoť jest ta vaše hodina, a moc temnosti.',
        54: 'I javše jej, vedli, a uvedli do domu nejvyššího kněze {biskupova}. Petr pak šel za ním zdaleka.',
        55: 'A když zanítili oheň u prostřed síně, a posadili se vůkol, sedl Petr mezi ně.',
        56: 'A uzřevši ho jedna děvečka, an sedí u ohně, a pilně naň pohleděvši, řekla: I tento byl s ním.',
        57: 'On pak zapřel ho, řka: Ženo, neznám ho.',
        58: 'A po malé chvíli jiný, vida jej, řekl: I ty z nich jsi. Petr pak řekl: Ó člověče, nejsem.',
        59: 'A potom asi po jedné hodině jiný potvrzoval, řka: V pravdě i tento s ním byl, nebo také Galilejský jest.',
        60: 'I řekl Petr: Člověče, nevím, co pravíš. A hned, když on ještě mluvil, kohout zazpíval.',
        61: 'I obrátiv se Pán, pohleděl na Petra. I rozpomenul se Petr na slovo Páně, kterak jemu byl řekl: Že prvé než kohout zazpívá, třikrát mne zapříš.',
        62: 'I vyšed ven Petr, plakal hořce.',
        63: 'Muži pak ti, kteříž drželi Ježíše, posmívali se jemu, tepouce ho.',
        64: 'A zakrývajíce ho, bili jej v tvář, a tázali se ho, řkouce: Prorokuj, kdo jest, kterýž tebe udeřil?',
        65: 'A jiného mnoho, rouhajíce se, mluvili proti němu.',
        66: 'A když byl den, sešli se starší lidu a přední kněží {biskupové} a zákonníci, a vedli ho do rady své,',
        67: 'Řkouce: Jsi-li ty Kristus? Pověz nám. I dí jim: Povím-li vám, nikoli neuvěříte.',
        68: 'A pakli se vás co otíži, neodpovíte mi, ani nepropustíte.',
        69: 'Od této chvíle Syn člověka sedne na pravici moci Boží.',
        70: 'I řekli všickni: Tedy jsi ty Syn Boží? On pak řekl jim: Vy pravíte, nebo já jsem.',
        71: 'A oni řekli: Což ještě potřebujeme svědectví? Však jsme sami slyšeli z úst jeho.',
    },
    23: {
        1: 'Tehdy povstavši všecko množství jich, vedli jej ku Pilátovi.',
        2: 'A počali naň žalovati, řkouce: Tohoto jsme nalezli, an převrací lid, a brání daně dávati císaři, pravě se býti Kristem králem.',
        3: 'Pilát pak otázal se ho, řka: Jsi-liž ty král ten Židovský? A on odpověděv, řekl jemu: Ty pravíš.',
        4: 'I dí Pilát předním kněžím {biskupům} a zástupům: Žádné viny nenalézám na tomto člověku.',
        5: 'Oni pak více se silili, řkouce: Bouříť lid, uče po všem Judstvu, počav od Galilee až sem.',
        6: 'Tedy Pilát uslyšav o Galilei, otázal se, byl-li by člověk Galilejský.',
        7: 'A když zvěděl, že by byl z panství Heródesova, poslal jej k Heródesovi, kterýž také v Jeruzalémě byl v ty dni.',
        8: 'Heródes pak uzřev Ježíše, zradoval se velmi. Nebo dávno žádal viděti jej, proto že mnoho o něm slýchal, a nadál se, že nějaký div uzří od něho učiněný.',
        9: 'I tázal se ho mnohými řečmi, ale on jemu nic neodpovídal.',
        10: 'Stáli pak přední kněží {biskupové} a zákonníci, tuze na něj žalujíce.',
        11: 'A pohrdna jím Heródes s svým rytířstvem, a naposmívav se jemu, oblékl jej v roucho bílé, i odeslal zase ku Pilátovi.',
        12: 'I učiněni jsou přátelé Pilát s Heródesem v ten den. Nebo před tím nepřátelé byli vespolek.',
        13: 'Pilát pak svolav přední kněží {biskupy} a úřadné osoby i lid,',
        14: 'Řekl jim: Dali jste mi tohoto člověka, jako by lid odvracel, a aj, já před vámi vyptávaje se ho, žádné viny jsem nenalezl na tom člověku v tom, což na něj žalujete.',
        15: 'Ano ani Heródes; nebo odeslal jsem vás k němu, a aj, nic hodného smrti nestalo se jemu.',
        16: 'Protože potrestaje, propustím ho.',
        17: 'Musil pak propouštívati jim jednoho v svátek.',
        18: 'Protož zkřiklo spolu všecko množství, řkouce: Zahlaď tohoto, a propusť nám Barabáše.',
        19: 'Kterýž byl pro bouřku nějakou v městě učiněnou a pro vraždu vsazen do žaláře.',
        20: 'Tedy Pilát opět mluvil, chtěje propustiti Ježíše.',
        21: 'Oni pak vždy volali, řkouce: Ukřižuj ho, ukřižuj.',
        22: 'A on potřetí řekl jim: Což pak zlého učinil tento? Žádné příčiny smrti nenalezl jsem na něm. Protož potresce, propustím ho.',
        23: 'Oni pak předce dotírali křikem velikým, žádajíce, aby byl ukřižován. A rozmáhali se hlasové jejich i předních kněží {biskupů}.',
        24: 'Pilát pak přisoudil, aby se naplnila žádost jejich.',
        25: 'I propustil jim toho, kterýž pro bouřku a vraždu vsazen byl do žaláře, za něhož prosili, ale Ježíše vydal k vůli jejich.',
        26: 'A když jej vedli, chytivše Šimona nějakého Cyrenenského, jdoucího s pole, vložili na něj kříž, aby nesl za Ježíšem.',
        27: 'I šlo za ním veliké množství lidu i žen, kteréž plakaly a kvílily ho.',
        28: 'A obrátiv se k nim Ježíš, dí: Dcery Jeruzalémské, neplačte nade mnou, ale raději samy nad sebou plačte a nad svými dětmi.',
        29: 'Nebo aj, dnové jdou, v nichž řeknou: Blahoslavené neplodné, a břicha, kteráž nerodila, a prsy, kteréž nekrmily.',
        30: 'Tehdyť počnou říci k horám: Padněte na nás, a pahrbkům: Přikrejte nás.',
        31: 'Nebo poněvadž na zeleném dřevě toto se děje, i co pak bude na suchém?',
        32: 'Vedeni pak byli i jiní dva zločinci, aby spolu s ním byli ukřižováni.',
        33: 'A když přišli na místo, kteréž slove popravištné, tu jej ukřižovali, i ty zločince, jednoho na pravici, druhého pak na levici.',
        34: 'Tedy Ježíš řekl: Otče, odpusť jim, neboť nevědí, co činí. A rozdělivše roucho jeho, metali los.',
        35: 'I stál lid, dívaje se. A posmívali se jemu knížata {biskupové} s nimi, řkouce: Jinýmť spomáhal, nechať pomůže sám sobě, jestliže on jest Kristus, ten Boží zvolený.',
        36: 'Posmívali se pak jemu i žoldnéři, přistupujíce a octa podávajíce jemu,',
        37: 'A říkajíce: Jsi-li ty král ten Židovský, spomoziž sám sobě.',
        38: 'A byl také i nápis napsaný nad ním, literami Řeckými a Latinskými a Židovskými: Tento jest král Židovský.',
        39: 'Jeden pak z těch zločinců, kteříž s ním viseli, rouhal se jemu, řka: Jsi-li ty Kristus, spomoziž sobě i nám.',
        40: 'A odpověděv druhý, trestal ho, řka: Ani ty se Boha nebojíš, ješto jsi v témž potupení?',
        41: 'A my zajisté spravedlivě, nebo hodnou pomstu za skutky své béřeme, ale tento nic zlého neučinil.',
        42: 'I dí Ježíšovi: Pane, rozpomeň se na mne, když přijdeš do království svého.',
        43: 'I řekl mu Ježíš: Amen pravím tobě, dnes budeš se mnou v ráji.',
        44: 'A bylo okolo hodiny šesté. I stala se tma po vší zemi až do hodiny deváté.',
        45: 'I zatmělo se slunce, a opona chrámová roztrhla se napoly.',
        46: 'A zvolav Ježíš hlasem velikým, řekl: Otče, v ruce tvé poroučím ducha svého. A to pověděv, umřel.',
        47: 'A viděv centurio, co se stalo, velebil Boha, řka: Jistě člověk tento spravedlivý byl.',
        48: 'A všickni zástupové, přítomní tomu divadlu, hledíce na to, co se dálo, tepouce prsy své, navracovali se.',
        49: 'Stáli pak všickni známí jeho zdaleka, hledíce na to, i ženy, kteréž byly přišly za ním z Galilee.',
        50: 'A aj, muž jménem Jozef, jeden z úřadu, muž dobrý a spravedlivý,',
        51: 'Kterýž byl nepovolil radě a skutku jejich, z Arimatie města Judského, kterýž také očekával království Božího;',
        52: 'Ten přistoupiv ku Pilátovi, vyprosil tělo Ježíšovo.',
        53: 'A složiv je, obvinul v kment, a pochoval je v hrobě vytesaném, v kterémž ještě nikdy nebyl žádný pochován.',
        54: 'A byl den připravování, a sobota se začínala.',
        55: 'Šedše pak také za ním ženy, kteréž byly s Ježíšem přišly z Galilee, pohleděly na hrob, a kterak pochováno bylo tělo jeho.',
        56: 'Vrátivše se pak, připravily vonné věci a masti, ale v sobotu odpočinuly, podlé přikázaní.',
    },
    24: {
        1: 'Prvního pak dne po sobotě velmi ráno šly k hrobu, nesouce vonné věci, kteréž byly připravily, a některé jiné s nimi.',
        2: 'I nalezly kámen odvalený od hrobu.',
        3: 'A všedše, nenalezly těla Pána Ježíše.',
        4: 'I stalo se, když ony se toho užasly, aj, muži dva postavili se podlé nich v rouše stkvoucím.',
        5: 'Když se pak ony bály, a sklonily tváři své k zemi, řekli jim: Co hledáte živého s mrtvými?',
        6: 'Neníť ho tuto, ale vstalť jest. Rozpomeňte se, kterak mluvil vám, když ještě v Galilei byl,',
        7: 'Řka: Že Syn člověka musí vydán býti v ruce hříšných lidí, a ukřižován býti, a v třetí den z mrtvých vstáti.',
        8: 'I rozpomenuly se na slova jeho.',
        9: 'A navrátivše se od hrobu, zvěstovaly to všecko těm jedenácti i jiným všechněm.',
        10: 'Byly pak Maria Magdaléna a Johanna a Maria Jakubova, a jiné s nimi, kteréž vypravovaly to apoštolům.',
        11: 'Ale oni měli za bláznovství slova jejich, a nevěřili jim.',
        12: 'Tedy Petr vstav, běžel k hrobu, a pohleděv do něho, uzřel prostěradla, ana sama leží. I odšel, divě se sám v sobě, co se to stalo.',
        13: 'A aj, dva z nich šli toho dne do městečka, kteréž bylo vzdálí od Jeruzaléma honů šedesáte, jemuž jméno Emaus.',
        14: 'A rozmlouvali vespolek o těch všech věcech, kteréž se byly staly.',
        15: 'I stalo se, když rozmlouvali, a sebe se otazovali, že i Ježíš, přiblíživ se, šel s nimi.',
        16: 'Ale oči jejich držány byly, aby ho nepoznali.',
        17: 'I řekl jim: Které jsou to věci, o nichž rozjímáte vespolek, jdouce, a jste smutní?',
        18: 'A odpověděv jeden, kterémuž jméno Kleofáš, řekl jemu: Ty sám jsi z příchozích do Jeruzaléma, ještos nezvěděl, co se stalo v něm těchto dnů?',
        19: 'Kterýmž on řekl: I co? Oni pak řekli jemu: O Ježíšovi Nazaretském, kterýž byl muž prorok, mocný v slovu i v skutku, před Bohem i přede vším lidem,',
        20: 'Totiž kterak jej vydali přední kněží {biskupové} a knížata naše na odsouzení k smrti, i ukřižovali jej.',
        21: 'My pak jsme se nadáli, že by on měl vykoupiti Izraele. Ale nyní tomu všemu třetí den jest dnes, jakž se to stalo.',
        22: 'Ale i ženy některé z našich zděsily nás, kteréž ráno byly u hrobu.',
        23: 'A nenalezše tělo jeho, přišly, pravíce, že také vidění andělské viděly, kteříž praví, že by živ byl.',
        24: 'I chodili někteří z našich k hrobu, a nalezli tak, jakž pravily ženy, ale jeho neviděli.',
        25: 'Tedy on řekl jim: Ó nesmyslní a zpozdilí srdcem k věření všemu tomu, což mluvili proroci.',
        26: 'Zdaliž nemusil těch věcí trpěti Kristus a vjíti v slávu svou?',
        27: 'A počav od Mojžíše a všech proroků, vykládal jim všecka ta písma, kteráž o něm byla.',
        28: 'I přiblížili se k městečku, do kteréhož šli, a on potrh se, jako by chtěl dále jíti.',
        29: 'Ale přinutili ho, řkouce: Zůstaň s námi, nebo se již připozdívá, a den se nachýlil. I všel, aby s nimi zůstal.',
        30: 'I stalo se, když seděl s nimi za stolem, vzav chléb, dobrořečil, a lámaje, podával jim.',
        31: 'I otevříny jsou oči jejich, a poznali ho. On pak odnesl se od nich.',
        32: 'I řekli vespolek: Zdaliž srdce naše v nás nehořelo, když mluvil nám na cestě, a když otvíral nám písma?',
        33: 'A vstavše v tu hodinu, vrátili se do Jeruzaléma, a nalezli shromážděných těch jedenácte, a ty, kteříž s nimi byli,',
        34: 'Ani praví: Že vstal Pán právě, a ukázal se Šimonovi.',
        35: 'I vypravovali oni také to, co se stalo na cestě, a kterak ho poznali v lámání chleba.',
        36: 'A když oni o tom rozmlouvali, postavil se Ježíš u prostřed nich, a řekl jim: Pokoj vám.',
        37: 'Oni pak zhrozivše se a přestrašeni byvše, domnívali se, že by ducha viděli.',
        38: 'I dí jim: Co se strašíte, a proč myšlení vstupují na srdce vaše?',
        39: 'Vizte ruce mé i nohy mé, já zajisté jsem ten. Dotýkejte se mne a vizte; neboť duch těla a kostí nemá, jako mne vidíte míti.',
        40: 'A pověděv to, ukázal jim ruce i nohy.',
        41: 'Když pak oni ještě nevěřili pro radost, ale divili se, řekl jim: Máte-li tu co k jídlu?',
        42: 'A oni podali jemu kusu ryby pečené a plástu strdi.',
        43: 'A vzav, pojedl před nimi,',
        44: 'A řekl jim: Tatoť jsou slova, kteráž jsem mluvil vám, ještě byv s vámi: Že se musí naplniti všecko, což psáno jest v zákoně Mojžíšově a v prorocích i v žalmích o mně.',
        45: 'Tedy otevřel jim mysl, aby rozuměli písmům.',
        46: 'A řekl jim: Takť jest psáno, a tak musil Kristus trpěti, a třetího dne z mrtvých vstáti,',
        47: 'A aby bylo kázáno ve jménu jeho pokání a odpuštění hříchů mezi všemi národy, počna od Jeruzaléma.',
        48: 'Vy pak jste svědkové toho.',
        49: 'A aj, já pošli zaslíbení Otce svého na vás. Vy pak čekejte v městě Jeruzalémě, dokudž nebudete oblečeni mocí s výsosti.',
        50: 'I vyvedl je ven až do Betany, a pozdvih rukou svých, dal jim požehnání.',
        51: 'I stalo se, když jim žehnal, bral se od nich, a nesen jest do nebe.',
        52: 'A oni poklonivše se jemu, navrátili se do Jeruzaléma s radostí velikou.',
        53: 'A byli vždycky v chrámě, chválíce a dobrořečíce Boha. Amen.',
    },
}
